SELECT 'moj-all-verified-judgments-review-002-chunk-134' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"e52a531b-bbbd-521d-b6c4-6ffef69a7f09","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -اختاس -اختاس محاسب من الصندوق -خيانة أمانة -إقرار بالدعوى -ثبوت إدانة -تعزير بالسجن واجللد -تغليظ","document_number":"34216087","case_number":"34214538","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بأبو عريش املكلف والقائم بعمل املكتب القضائي الثاني","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/19","year":"1434","subject":"سرقة -اختاس -اختاس محاسب من الصندوق -خيانة أمانة -إقرار بالدعوى -ثبوت إدانة -تعزير بالسجن واجللد -تغليظ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34216087 :‬تاريخه‪1434/05/19 :‬هـ‬\n                           ‫رقم الدعوى‪34214538:‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34238495‬تاريخه‪1434/6/12 :‬هـ‬\n\n\n\n       ‫ســرقة ‪ -‬اختــاس ‪ -‬اختــاس محاســب مــن الصنــدوق ‪ -‬خيانــة أمانــة‬\n       ‫‪ -‬إقــرار بالدعــوى ‪ -‬ثبــوت إدانــة ‪ -‬تعزيــر بالســجن واجللــد ‪ -‬تغليــظ‬\n                                                                      ‫العقوبــة‪.‬‬\n\n\n\n\n                     ‫‪1 .1‬قول اهلل تعالى «وال تعتدوا إن اهلل ال يحب املعتدين»‬\n       ‫‪2 .2‬قــول النبــي صلــى اهلل عليــه وســلم «آيــة املنافــق ثــاث وذكــر منهــا‬\n                                                               ‫وإذا ائتمــن خــان»‬\n       ‫‪3 .3‬قــول النبــي صلــى اهلل عليــه وســلم «إن دمائكــم وأموالكم وأعراضكم‬\n                                                                    ‫حــرام عليكم»‬\n\n\n\n       ‫اتهــام املدعــي العــام للمدعــى عليــه باختــاس مبلــغ مالــي مــن خزنــة‬\n       ‫مجمــع ‪ ........‬حيــث كان يعمــل مســؤوال عــن الصنــدوق وطلــب إثبــات‬\n       ‫مــا أســند إليــه واحلكــم بتعزيــره شــرعا‪ ،‬حيــث إنــه طلــب مــن املدعــى‬\n       ‫عليــه جــردا علــى خزانــة املؤسســة للمجمــع كامــا حيــث أنــه كان‬\n       ‫املســؤول عنهــا ومت جــرد اخلزانــة واتضــح وجــود عجــز يف اخلزانــة قــدره‬\n       ‫ألفــا ومائتــان وخمســة وخمســون‬ ‫‪ 333.255‬ثالثمائــة وثالثــة وثالثــون ً‬\n       ‫ريــاال للمدعــو ‪ ....‬وباســتجواب املدعــى عليــه بعــد إحاطتــه بالتهمــة‬\n\n‫‪349‬‬\n\f‫املنســوبة إليــه أفــاد أنــه لــم يختلــس املبلــغ بالكامــل وإمنــا اختلــس مبل ًغــا‬\n‫ماليــا وقــدره ‪ 40.000‬أربعــون ألــف ريــاال حيــث كان يعمــل يف مؤسســة‬\n‫‪ ...‬مســؤوال عــن اخلزانــة وأنــه لــم يكــن الوحيــد الــذي يســجل فواتيــر‪،‬‬\n‫بــل كل العاملــن تســببوا يف العجــز ‪ ،‬وأمــا ســبب قيامــه باختــاس‬\n‫املبلــغ املذكــور فذكــر أن لديــه جمعيــة ويريــد الــزواج ومــن َثــم يعيدهــا‬\n‫‪ ،‬وأنــه مســتعد بتســديد املبلــغ للمؤسســة عــن طريــق األقســاط وصــادق‬\n‫حتقيقــا وقــد أســفر التحقيــق عــن توجيــه االتهــام للمدعــى‬ ‫ً‬         ‫علــى أقوالــه‬\n‫عليــه باختــاس مبلــغ مالــي وقــدره ‪ 333.255‬ثالثمائــة وثالثــة وثالثــون‬\n‫ألفــا ومائتــان وخمســة وخمســون ريــاال مــن خزنــة مجمــع ‪ ....‬حيــث كان‬          ‫ً‬\n‫يعمــل مســؤوال عــن الصنــدوق لديهــم بالبحــث عــن ســوابقه لــم يعثــر لــه‬\n                                           ‫علــى ســوابق مســجلة حتــى تاريخــه ‪.‬‬\n                                      ‫‪ -‬أقر املدعى عليه مبا جاء يف الدعوى ‪.‬‬\n                                   ‫‪ -‬ثبت إدانة املدعى عليه واحلكم مبا يلي ‪:‬‬\n    ‫‪ -1‬بالسجن ملدة عشرة أشهر من تاريخ إيقافه على ذمة هذه القضية‪.‬‬\n‫‪ -2‬باجللــد خمســمائة جلــده مفرقــة علــى عشــر دفعــات بــن كل دفعــة‬\n‫وأخــرى مــدة ال تقــل عــن عشــرة‪ ،‬قــرر املدعــي العــام عــدم القناعــة وطلــب‬\n‫االســتئناف بــدون الئحــة وقــرر املدعــى عليــه القناعــة‪ ،‬تصديــق احلكــم‬\n                                                       ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد فلــدي‬\n‫أنــا ‪ ....‬رئيــس احملكمــة العامــة بأبــو عريــش املكلــف والقائــم بعمــل‬\n‫املكتــب القضائــي الثانــي وبنــاء علــى املعاملــة الــواردة إلينــا مــن دائــرة‬\n\n                                                                                           ‫‪350‬‬\n\f      ‫التحقيــق واالدعــاء العــام بأبــو عريــش برقــم ه ـ ج‪ 1058/2/3‬وتاريــخ‬\n      ‫‪1434/5/5‬ه ـ واحملالــة إلينا بشــرح رئيــس احملكمة برقم ‪34214538‬‬\n      ‫وتاريــخ ‪1434/5/8‬ه ـ واملقيــدة باحملكمــة برقــم ‪ 341125901‬وتاريــخ‬\n      ‫‪1434/5/7‬ه ـ ففــي يــوم األحــد املوافــق ‪1434/5/19‬ه ـ افتتحــت‬\n      ‫اجللســة األولــى يف متــام الســاعة العاشــرة وفيهــا حضــر املدعــي العــام‬\n      ‫بدائــرة التحقيــق واالدعــاء العــام مبحافظــة أبــو عريــش ‪ .....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....‬واملفــوض باخلطــاب رقــم ه ـ‬\n      ‫ج ‪ 513/630/‬وتاريــخ ‪1429/11/3‬ه ـ وأدعــى قائــا بصفتــي مدعيــا‬\n      ‫عامــا بدائــرة االدعــاء العــام مبحافظــة أبــو عريــش أدعــي علــى ‪29 ....‬‬\n      ‫عامــا ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬مــودع بقســم‬       ‫ً‬\n      ‫ســجن أبــي عريــش مبوجــب أمــر متديــد التوقيــف واإلحالــة رقــم ‪3348‬‬\n      ‫وتاريــخ ‪1434/2/19‬ه ـ لكــون جرميتــه مــن اجلرائــم املوجبــة للتوقيــف‬\n      ‫ويعــد إيقافــه مــن تاريــخ‬  ‫اســتنا ًدا للقــرار الــوزاري رقــم ‪ 1900‬وتاريــخ ُ‬\n      ‫القبــض عليــه بتاريــخ إنــه يف متــام الســاعة التاســعة والنصــف مــن صبــاح‬\n      ‫يــوم االثنــن ‪1434/2/4‬ه ـ حضــر لشــرطة صبيــا ‪ ....‬مفيــدا أنــه يف بدايــة‬\n      ‫شــهر رمضــان مــن العــام املاضــي طلــب مــن املدعــى عليــه جــردا علــى‬\n      ‫خزانــة املؤسســة للمجمــع كامــا حيــث أنــه كان املســؤول عنهــا وبعــد‬\n      ‫ذلــك لــم يعــد يــداوم أبــدا ومت االتصــال عليــه وإبالغــه بأنــه ســوف يقــوم‬\n      ‫بإبــاغ الشــرطة يف عــدم حضــوره وحضــر معــه إخوانــه ومت جــرد اخلزانــة‬\n      ‫واتضــح وجــود عجـ ٍـز يف اخلزانــة قــدره ‪ 333255‬ثالثمائــة وثالثــة وثالثــون‬\n      ‫ألفــا ومائتــان وخمســة وخمســون ريــاال للمدعــو ‪ ....‬وباســتجواب املدعــى‬       ‫ً‬\n      ‫عليــه بعــد إحاطتــه بالتهمــة املنســوبة إليــه أفــاد أنــه لــم يختلــس املبلــغ‬\n      ‫بالكامــل وإمنــا اختلــس مبل ًغــا ماليــا وقــدره ‪ 40000‬أربعــون ألفــا ريــاال‬\n\n\n‫‪351‬‬\n\f‫وكان ذلــك يف عــام ‪ 2011‬شــهر ‪ 7‬أو ‪ 8‬ال يعلــم حتديــدا حيــث كان‬\n‫يعمــل يف مؤسســة ‪ ...‬مســؤوال عــن اخلزانــة وأنــه لــم يكــن الوحيــد الــذي‬\n‫يســجل فواتيــر بــل كل العاملــن تســببوا يف العجــز وأمــا ســبب قيامــه‬\n‫باختــاس املبلــغ املذكــور فذكــر أن لديــه جمعيــة ويريــد الــزواج ومــن‬\n‫َثــم يعيدهــا وأنــه مســتعد بتســديد املبلــغ للمؤسســة عــن طريــق األقســاط‬\n‫حتقيقــا وقــد أســفر التحقيــق عــن توجيــه االتهــام‬\n                                                   ‫ً‬     ‫وصــادق علــى أقوالــه‬\n‫للمدعــى عليــه باختــاس مبلــغ مالــي وقــدره ‪ 333255‬ثالثمائــة وثالثــة‬\n‫ألفــا ومائتــان وخمســة وخمســون ريــاال مــن خزنــة مجمــع ‪...‬‬    ‫وثالثــون ً‬\n‫حيــث كان يعمــل مســؤوال عــن الصنــدوق لديهــم وذلــك لألدلــة والقرائن‬\n‫التاليــة مــا جــاء يف إقــرار حتقيق ـ ًا املــدون ص ‪ 1‬مــن دفتــر التحقيــق لفــة‬\n‫رقــم ‪ 1‬مــا جــاء يف أقوالــه املدونــة ص ‪ 14‬مــن دفتــر التحقيــق لفــة رقــم ‪2‬‬\n‫مــا جــاء يف تقريــر احملاســب القانونــي املرفــق لفــة ر قــم ‪ 3‬وبالبحــث عــن‬\n‫ســوابقه لــم يعثــر لــه علــى ســوابق مســجلة حتــى تاريخــه وحيــث أن مــا‬\n‫أقــدم عليــه املدعــى عليــه فعــل محــرم شــرعا ومعاقــب عليــه لــذا أطلــب‬\n‫إثبــات مــا أســند إليــه واحلكــم بتعزيــره شــرعا علمــا بــأن احلــق اخلــاص‬\n‫قائمــا وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه بعــد‬‫مــا زال ً‬\n‫التأكــد مــن هويتــه وأهليتــه املعتبــرة شــرعا أجــاب قائــا مــا ذكــره‬\n‫املدعــي العــام مــن قيامــي باختــاس مبلــغ مالــي وقــدره‪ 333255‬ريــاال‬\n‫مــن خزنــة مجمــع ‪ ...‬فصحيــح هكــذا أجــاب عقــب ذلــك جــرى االطــاع‬\n‫علــى كــرت ســوابق املدعــى عليــه لفــة رقــم‪ 19‬فوجدتهــا خاليــة مــن‬\n‫الســوابق عقــب ذلــك جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه‬\n‫لفــه رقــم‪ 9‬أنهمــا أوقفــا بتاريــخ ‪1434/2/16‬ه ـ فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة ومبــا أن املدعــي العــام يتهــم املدعــى عليــه بقيامــه‬\n\n\n                                                                                      ‫‪352‬‬\n\f      ‫ألفــا‬\n          ‫باختــاس مبلــغ مالــي وقــدره ‪ 333255‬ثالثمائــة وثالثــة وثالثــون ً‬\n      ‫ومائتــان وخمســة وخمســون ريــاال مــن خزنــة مجمــع ‪ ...‬ومبــا أن املدعــى‬\n      ‫عليــه صــادق علــى دعــوى املدعــي العــام ومبــا أن مــا قــام بــه املدعــى عليــه‬\n      ‫فعــل محــرم شــرعا ولقولــه تعالــى» وال تعتــدوا إن اهلل ال يحــب املعتديــن»‬\n      ‫ولقــول النبــي صلــى اهلل عليــه وســلم أيــة املنافــق ثــاث وذكــر منهــا وإذا‬\n      ‫ائتمــن خــان ونظــرا لكــون املدعــى عليــه اختلــس ممــن ائتمنــه ولقــول‬\n      ‫النبــي صلــى اهلل عليــه وســلم «إن دمائكــم وأموالكــم وأعراضكــم‬\n      ‫حــرام عليكــم» كمــا يتوجــب مــع ذلــك تغليــظ العقوبــة ولذلــك كلــه‬\n      ‫وألجــل احلــق العــام فقــد قــررت مــا يلــي أوال ثبــت لــدي إدانــة املدعــى عليــه‬\n      ‫بقيامــه باختــاس مبلــغ مالــي وقــدره ‪ 333.255‬ثالثمائــة وثالثــة وثالثون‬\n      ‫ألفــا ومائتــان وخمســة وخمســون ريــاال مــن خزنــة مجمــع ‪ ...‬ثانيــا يعــزر‬     ‫ً‬\n      ‫املدعــى عليــه بالســجن ملــدة عشــرة أشــهر مــن تاريــخ إيقافــه علــى ذمــة‬\n      ‫هــذه القضيــة ثالثــا يعــزر املدعــى عليــه باجللــد خمســمائة جلــده مفرقــة‬\n      ‫علــى عشــر دفعــات بــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيــام‬\n      ‫وبجميــع مــا تقــدم حكمــت وبعــرض احلكــم علــى املدعــي العــام قــرر‬\n      ‫عــدم القناعــة بــدون الئحــة اعتراضيــة وبعــرض احلكــم علــى املدعــى‬\n      ‫عليــه قــرر القناعــة عليــه أمــرت برفــع كامــل أوراق املعاملــة حملكمــة‬\n      ‫االســتئناف لتدقيــق احلكــم وحتــى ال يخفــى جــرى تدوينــه وبــاهلل‬\n      ‫التوفيــق وأقفلــت اجللســة يف متــام الســاعة احلاديــة عشــر وصلــى اهلل وســلم‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/5/19‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بأبــي عريــش املكلــف‬\n\n\n‫‪353‬‬\n\f‫الشــيخ ‪ .... /‬برقــم ‪ 341125901‬وتاريــخ ‪1434/5/21‬ه ـ املرفــق بهــا‬\n‫القرار الصادر من فضيلته برقم ‪ 34216087‬وتاريخ ‪1434/5/19‬هـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد ‪ ( ....‬ســعودي اجلنســية ) يف قضيــة‬\n‫(اختــاس مبلــغ مالــي) علــى الصفــة املوضحــة يف القــرار املتضمن حكم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                                  ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪354‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":349,"source_page_end":354,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"050dc683a5da6ccf10c8513827fa83e8a896d8d0c621f3f6e617b4f12546c6f1","normalized_text_hash":"58ee7f079a099f88461fdb07edf95117581b7438f245d9ade2472f7bb33457ff","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p349-34216087"},{"id":"211102cc-bf36-5cc3-8f74-fa5a70984151","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة حافظة نقود من داخل سيارة -تشديد العقوبة لوجود عدة سوابق قضائية -إقرار املدعى عليه -تعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","document_number":"34344724","case_number":"34478707","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/29","year":"1434","subject":"سرقة -سرقة حافظة نقود من داخل سيارة -تشديد العقوبة لوجود عدة سوابق قضائية -إقرار املدعى عليه -تعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34344724 :‬تاريخه‪1434/10/29 :‬هـ‬\n                           ‫رقم الدعوى‪34478707 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34354347‬تاريخه‪1434/11/9 :‬هـ‬\n\n\n\n       ‫ســرقة ‪ -‬ســرقة حافظــة نقــود مــن داخــل ســيارة ‪ -‬تشــديد العقوبــة‬\n       ‫لوجــود عــدة ســوابق قضائيــة ‪ -‬إقــرار املدعــى عليــه ‪ -‬تعزيــر بالســجن‬\n                                     ‫واجللــد والتوصيــة باإلبعــاد عــن البــاد‪.‬‬\n\n\n\n\n                                      ‫القاعدة الشرعية ( املرء مؤاخذ بإقراره ) ‪.‬‬\n\n\n\n\n       ‫اتهــام املدعــي العــام للمدعــى عليــه بســرقة حافظــة نقــود مــن ســيارة‬\n       ‫وطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــه‬\n       ‫وتشــديد العقوبــة عليــه لكثــرة ســوابقه التــي لــم تردعــه عقوباتهــا‪،‬‬\n       ‫حيــث إنــه تبلــغ ملركــز الشــرطة مــن قبــل املجنــي عليــه تعرضــه للســرقة‬\n       ‫مــن داخــل ســيارته وســرقة بطاقــات رســمية‪ ،‬وبتاريــخ الحــق تبــن أنــه‬\n       ‫مت القبــض علــى املدعــى عليــه املذكــور وبتفتيشــه عثــر علــى إثبــات‬\n       ‫شــخصي ورخصــة ســير لســيارة تعــود للمبلــغ‪ ،‬أقــر املدعــى عليــه مبــا‬\n       ‫جــاء يف الدعــوى ‪ ،‬فبنــاء علــى مــا تقــدم ويالحــظ كثــرة ســوابق املدعــى‬\n       ‫عليــه ‪ ،‬ثبــت إدانــة املدعــى عليــه وصــدر احلكــم بالســجن ســنتني ابتــداء‬\n       ‫مــن تاريــخ إيقافــه يف هــذه القضيــة‪ ،‬وجلــده ثمامنائــة جلــدة مفرقــة علــى‬\n       ‫ســتة عشــر دفعــة متســاوية كل دفعــة خمســون جلــدة بــن كل دفعــة‬\n\n‫‪355‬‬\n\f‫واألخــرى مــدة ال تقــل عــن عشــرة أيــام وأن يكــون اجللــد يف مــكان‬\n‫عــام‪ ،‬والتوصيــة بإبعــاده عــن البــاد بعــد انتهــاء محكوميتــه‪ ،‬وقــرر‬\n‫املدعــى العــام االعتــراض وطلــب االســتئناف بــدون الئحــة وقــرر املدعــى‬\n           ‫عليــه القناعــة‪ ،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بحائــل برقــم ‪ 34478707‬وتاريــخ ‪1434/10/27‬ه ـ املقيــدة‬         ‫ّ‬\n‫باحملكمــة برقــم ‪ 342439592‬وتاريــخ ‪1434/10/27‬ه ـ ففــي يــوم‬\n‫اخلميــس املوافق‪1434/10/29‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 00‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ .....‬بصفتــه مدعي ـ ًا عام ـ ًا يف دائــرة االدعــاء‬\n‫العــام بفــرع هيئــة التحقيــق و االدعــاء العــام مبنطقــة حائــل وأدعــى‬\n‫علــى احلاضــر معــه ‪ ....-1‬فلســطيني اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫رقــم (‪ )....‬قائــا يف دعــواه ‪ .‬تاريــخ ‪1434/8/16‬ه ـ تبلــغ مركــز شــرطة‬\n‫بريــدة الشــمالي مــن قبــل املواطــن‪ .... /‬تعرضــه لســرقة اســتمارة ســيارته‬\n‫وبطاقــة األحــوال املدنيــة اخلاصــة بــه وبطاقــة هيئــة التخصصــات الطبيــة‬\n‫وبطاقــة اإلنعــاش القلبــي مــن داخــل ســيارته‪ .‬وبتاريــخ ‪1434/8/17‬ه ـ‬\n‫ورد ملركــز شــرطة بريــدة الشــمالي خطــاب مديــر شــرطة منطقــة حائــل‬\n‫رقــم (‪ )5699‬وتاريــخ ‪1434/8/17‬ه ـ املتضمــن أنــه مت القبــض علــى‬\n‫املدعــى عليــه املذكــور وبتفتيشــه عثــر علــى إثبــات شــخصي ورخصــة‬\n‫ســير لســيارة مــن نــوع ‪ ...‬تعــود للمبلــغ‪ .‬وباســتجواب املدعــى عليــه أقــر‬\n‫بقيامــه بســرقة محفظــة مــن ســيارة نــوع ‪ ....‬كانــت متوقفــة يف مواقــف‬\n\n                                                                                       ‫‪356‬‬\n\f      ‫املستشــفى ‪ ،‬وأضــاف أنــه وجــد الســيارة غيــر مقفلــة ووجــد بداخلهــا‬\n      ‫احملفظــة فقــام بفتــح الســيارة وأخــذ احملفظــة مــن داخلهــا‪ .‬وقــد أســفر‬\n      ‫التحقيــق معــه عــن اتهامــه بســرقة محفظــة مــن ســيارة بداخلهــا بطاقــة‬\n      ‫األحــوال املدنيــة واســتمارة ســيارة وبطاقــة هيئــة التخصصــات الطبيــة‬\n      ‫وبطاقــة اإلنعــاش القلبــي عائــدة للمبلــغ‪ .... /‬وذلــك لألدلــة والقرائــن‬\n      ‫التاليــة ‪ - 1 :‬مــا جــاء باعترافــه املنــوه عنــه املــدون علــى الصفحــة رقــم‬\n      ‫(‪ 9‬ـ ـ ‪ )10‬مــن ملــف محاضــر إجــراءات االســتدالل األوليــة املرفــق لفــة‬\n      ‫(‪ ، 2.)1‬مــا جــاء بخطــاب مديــر شــرطة منطقــة حائــل رقــم (‪)5699‬‬\n      ‫وتاريــخ ‪1434/8/17‬ه ـ املرفــق صورتــه لفــة (‪ )6‬املتضمــن القبــض علــى‬\n      ‫املدعــى عليــه وبحوزتــه إثبــات شــخصي ورخصــة ســير لســيارة تعــود‬\n      ‫للمواطــن ‪.....‬وبالبحــث يف ســجله اجلنائــي اتضــح وجــود ســتة ســوابق‬\n      ‫األولــى هــروب وتغيــب والثانيــة ســرقة ســيارات ومنــازل والثالثــة دخــول‬\n      ‫منــزل لغــرض ســيء وســرقته والرابعــة حيــازة مخــدرات واخلامســة ســرقة‬\n      ‫ذهــب ومجوهــرات والسادســة ســرقة كيابــل‪ .‬وحيــث إن مــا أقــدم عليــه‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات إدانتــه مبــا أســند إليــه‬\n      ‫واحلكــم عليــه بعقوبــة تعزيريــه تزجــره وتــردع غيــره وتشــديد العقوبــة‬\n      ‫عليه لكثرة ســوابقه التي لم تردعه عقوباتها‪ .‬وبالل ــه التوفي ــق وبعرض‬\n      ‫دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي‬\n      ‫العــام يف دعــواه صحيــح وأنــا نــادم علــى فعلــي وتائــب إلــى اهلل تعالــى‬\n      ‫هكــذا أجــاب وبســؤال املدعــى عليــه عــن الســوابق املذكــورة أعــاه‬\n      ‫يف دعــوى املدعــي العــام أجــاب كلهــا صحيحــة ســوى ســرقة الكيابــل‬\n      ‫ودخــول منــزل والهــروب هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة وإقــرار املدعــى عليــه مبــا جــاء يف دعــوى املدعــي العــام وألنــه‬\n\n\n‫‪357‬‬\n\f‫ال عــذر ملــن أقــر ولكــون مــا فعلــه املدعــى عليــه يعتبــر تعديــا علــى حــق‬\n‫الغيــر بغيــر وجــه حــق وملــا تقــدم كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه‬\n‫مبــا نســب إليــه يف دعــوى املدعــي العــام ونظــر ًا لكثــرة ســوابقه وعــدم‬\n‫ارتداعــه فقــد حكمــت عليــه بأن يســجن ســنتني ابتداء مــن تاريخ إيقافه‬\n‫يف هــذه القضيــة وجلــده ثمامنائــة جلــدة مفرقــة علــى ســتة عشــر دفعــة‬\n‫متســاوية كل دفعــة خمســون جلــدة بــن كل دفعــة واألخــرى مــدة ال‬\n‫تقــل عــن عشــرة أيــام وأن يكــون اجللــد يف مــكان عــام وأوصيــت بإبعــاده‬\n‫عــن البــاد بعــد انتهــاء محكوميتــه وبعــرض احلكــم علــى املدعــي العــام‬\n‫واملدعــى عليــه قــرر املدعــي العــام عــدم القناعــة باحلكــم وطلــب رفــع‬\n‫املعاملــة حملكمــة االســتئناف بــدون الئحــة وقــرر املدعــى عليــه القناعــة‬\n‫باحلكــم وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n             ‫وصحبــه أجمعــن حــرر يف ‪1434/10/29‬ه ـ الســاعة ‪09.30‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولــى‬\n‫املختصــة بتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة‬\n‫حائــل علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بحائل‬\n‫برقــم‪ 342439592‬يف تاريــخ ‪1434 /11/5‬ه ـ واملقيــدة لدينــا برقــم‬\n‫‪ 342439592‬يف تاريــخ ‪1434 /11/6‬ه ـ املرفــق بهــا القــرار الشــرعي‬\n‫الصــادر مــن صاحــب الفضيلــة الشــيخ ‪ .... /‬القاضــي باحملكمة اجلزائية‬\n‫بحائــل برقــم ‪ 34344724‬يف تاريــخ ‪1434/10/29‬ه ـ اخلــاص بدعــوى‬\n‫املدعــي العــام ضــد‪( .....‬فلســطيني اجلنســية) مبوجــب اإلقامــة رقــم(‪)....‬‬\n‫بشــأن ســرقة وقــد تضمــن القــرار حكــم صاحــب الفضيلــة وفقــه اهلل‬\n‫علــى املدعــى عليــه علــى النحــو املفصــل يف القــرار املرفــق‪ ،‬وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة‪ .‬جــرت املصادقــة علــى ماحكــم‬\n\n\n                                                                                          ‫‪358‬‬\n\f      ‫بــه فضيلتــه بالقــرار املشــار إليــه‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى‬\n                                       ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪359‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":355,"source_page_end":359,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"776eadbb008a10f2fff823c37866d22c05a24ecadcaa7c0b27df58f2d5db1d93","normalized_text_hash":"b576cc94693ab81a89fe66200c44cc1b47c437b250a76b91d57873fd8d47ff61","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p355-34344724"},{"id":"0be81d8e-045f-5b1d-824f-7851d344c510","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة مبلغ مالي وجهاز جوال من داخل منزل -انتهاك حرمة منزل -تعظيم اجلناية يف بلد اهلل احلرام -ثبوت اإلدانة بالسرقة -تنازل عن احلق اخلاص -تعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","document_number":"34352474","case_number":"34489903","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/06","year":"1434","subject":"سرقة -سرقة مبلغ مالي وجهاز جوال من داخل منزل -انتهاك حرمة منزل -تعظيم اجلناية يف بلد اهلل احلرام -ثبوت اإلدانة بالسرقة -تنازل عن احلق اخلاص -تعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34352474 :‬تاريخه‪1434/11/06 :‬هـ‬\n                     ‫رقم الدعوى‪34489903 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34375433‬تاريخه‪1434/12/2 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة مبلــغ مالــي وجهــاز جــوال مــن داخــل منــزل ‪ -‬انتهــاك‬\n‫حرمــة منــزل ‪ -‬تعظيــم اجلنايــة يف بلــد اهلل احلــرام‪ -‬ثبــوت اإلدانــة‬\n‫بالســرقة ‪ -‬تنــازل عــن احلــق اخلــاص ‪ -‬تعزيــر بالســجن واجللــد‬\n                                         ‫والتوصيــة باإلبعــاد عــن البــاد‪.‬‬\n\n\n\n\n              ‫‪1 .1‬التعزير يشرع يف كل معصية ال حد فيها وال كفارة‪.‬‬\n‫‪2 .2‬تقديــر التعزيــر راجــع لنظــر احلاكــم مبــا يــراه محقق ـ ًا للزجــر‬\n                                                               ‫والــردع‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى ضــد املدعــى عليــه بدخــول منــزل ‪ ،‬وســرقة مبلــغ مالــي‬\n‫وجهــازي جــوال مــن املجنــي عليــه أثنــاء نومــه ‪ ،‬وطلــب املدعــي العــام‬\n‫إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة ‪ ،‬مت القبــض علــى‬\n‫املدعــى عليــه ووجــد أحــد اجلــوالت املســروقة بحوزتــه واعتــرف املدعــى‬\n‫عليــه بالدعــوى ‪ ،‬حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن‬\n‫واجللــد والتوصيــة بإبعــاده عــن البــاد ‪ ،‬مت تصديــق احلكــم من محكمة‬\n                                                                  ‫االســتئناف‪.‬‬\n\n\n                                                                                   ‫‪360‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 34489903‬وتاريــخ‬\n      ‫‪ 1434/11/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 342491638‬وتاريــخ‬\n      ‫‪ 1434/11/03‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1434/11/05‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 11 : 15‬وفيهــا حضــر املدعــي العــام بهيئــة‬\n      ‫التحقيــق واالدعــاء العــام باملدينــة املنــورة ‪..........‬و أدعــى علــى احلاضــر‬\n      ‫معــه مبجلــس احلكــم ‪..........‬باكســتاني اجلنســية مبوجــب رخصــة‬\n      ‫اإلقامــة الصــادرة مــن جــوازات املدينــة املنــورة بالرقــم ‪..........‬قائــا يف‬\n      ‫حتريــر دعــواه إنــه بتاريــخ ‪ 1434/8/16‬ه ـ أبلــغ ‪..........‬مينــي اجلنســية بأنــه‬\n      ‫بعــد إغــاق احملــل الــذي يعمــل بــه عنــد الســاعة الواحــدة ليــا اجتــه‬\n      ‫إلــي منزلــه الكائــن يف احلــي نفســه وكان بحوزتــه مبلغــا وقــدره ســبعة‬\n      ‫وعشــرون ألــف ريــال منهــا ســتة عشــر ألــف ريــال عائــدة لكفيلــه ‪..........‬و‬\n      ‫هــي إيــرادات املطعــم وثمانيــة اآلف عائــدة لــه شــخصيا والباقــي أمانــة‬\n      ‫لديــه وكان املبلــغ بداخــل جيــب بنطلونــه خــاص و وضعــه أســفل املخــدة‬\n      ‫التــي ينــام عليهــا وجــواره جهــازي جــوال خــاص بــه ثــم خلــد إلــى النــوم‬\n      ‫وعندمــا اســتيقظ عنــد الســاعة الثالثــة فجــرا وجــد البنطلــون الــذي بــه‬\n      ‫املبلــغ املســروق وأيضــا جهــازي اجلــوال غيــر موجديــن وال يتهــم أحــدا‬\n      ‫بالســرقة ومبعاينــة املنــزل رفــق األدلــة اجلنائيــة اتضــح أنــه يقــع يف حــي‬\n      ‫‪..........‬باملدينــة املنــورة وهــو عبــارة عــن منــزل شــعبي مكــون مــن دور‬\n      ‫واحــد ولــه بــاب بالناحيــة اجلنوبيــة ويطــل علــى شــارع صغيــر ولــه بــاب‬\n\n‫‪361‬‬\n\f‫حديــد ويوجــد ســلك حديــدي موصــل بقفــل البــاب وبــارز للخــارج يتــم‬\n‫مــن خاللــه فتــح البــاب حيــث إنــه ال يقومــون بإغــاق البــاب باملفتــاح وال‬\n‫يوجــد أي أثــار عنــف أو تكســير كمــا أنــه مبعاينــة املنــزل مــن الداخــل‬\n‫اتضــح أنــه املنــزل يحتــوي علــى غرفتــن ولــم يالحــظ أي أثــار بعثــرة أو‬\n‫عنــف أو تكســير علــى بــاب الغرفــة املتعرضــة للســرقة حيــث أفــاد املبلــغ‬\n‫أن املســروقات كانــت بداخــل بنطلــون خــاص بــه أســفل مخدتــه وســرق‬\n‫أثنــاء نومــه وبتاريــخ ‪ 1434/8/20‬ه ـ مت القبــض علــى املدعــى عليــه مــن‬\n‫قبــل قســم البحــث والتحــري باملركــز وضبــط أحــد اجلــواالت املســروقة‬\n‫بحوزتــه وباســتجواب املدعــى عليــه أفــاد أنــه عنــد الســاعة (‪ )2 : 30‬ليــا‬\n‫مــن يــوم ‪ 1434/8/16-15‬ه ـ ذهــب إلــى منــزل عمــال باملدينــة املنــورة‬\n‫وقــام بفتــح البــاب الرئيســي ملنزلهــم بواســطة حبــل مربــوط يف البــاب‬\n‫ودخــل لغرفــة العمــال ووجــد بداخلهــا أربعــة أشــخاص قــد نامــوا وقــام‬\n‫بســرقة جهــاز جــوال وبنطلــون أحــد العمــال وجــد بجــوار املخــدة عنــد نــوم‬\n‫أحــد األشــخاص عليــه ووجــد بداخلــه مبلــغ ســتة وعشــرين ألــف ريــال‬\n‫وقــام بصــرف املبلــغ علــى نفســه ولــم يتبقــى منــه ســوي مبلــغ ثمانيــة اآلف‬\n‫ومائــة ريــال وقــام بتســليمها للشــرطة وأضــاف أنــه قــام بالســرقة لوحــده‬\n‫ولــم يكــن معــه أحــد وباالنتقــال رفــق املدعــى عليــه لإلرشــاد علــى املنــزل‬\n‫الــذي اعتــرف بســرقته وذلــك للتأكــد مــن صحــة اعترافــه وقــد ارشــد‬\n‫املذكــور علــى منــزل املدعــو ‪..........‬مينــي اجلنســية بحــي ‪..........‬وأضــاف‬\n‫أن هــذا املنــزل هــو الــذي قــام بالدخــول إليــه وســرقة مبلــغ وقــدره ســتة‬\n‫وعشــرون ألــف ريــال كانــت يف بنطلــون أســفل مخــدة كان ينــام عليهــا‬\n‫املدعــى وقــد انتهــي التحقيــق إلــى توجيــه االتهــام إلــى املدعــى عليــه‬\n‫بدخــول منــزل وســرقة ســبعة وعشــرين ألــف ريــال مــن داخــل بنطلــون‬\n\n\n                                                                                      ‫‪362‬‬\n\f      ‫خــاص باملدعــي كان أســفل املخــدة التــي ينــام عليهــا وجهــازي جــوال‬\n      ‫أثنــاء نومــه وذلــك لألدلــة والقرائــن التاليــة مــا جــاء باعترافــه املــدون علــى‬\n      ‫ص ‪ 4‬مــن ملــف التحقيــق لفــة ‪ 2‬مــا جــاء مبحضــر القبــض لفــة (‪)16‬‬\n      ‫إرشــاده وإحضــاره جلــزء مــن املبلــغ املســروق مــا جــاء مبحضــر االســتدالل‬\n      ‫والتثبــت وإرشــاده للمنــزل املســروق املــدون علــى ص ‪ 4‬مــن ملــف التحقيق‬\n      ‫لفــة ‪ 1‬تعــرف املدعــي علــى جهــاز جوالــه حســب محضــر العــرض‬\n      ‫املــدون يف األوراق علــى ص ‪ 11‬مــن ملــف التحقيــق لفــة ‪ 1‬وبالبحــث‬\n      ‫عــن ســوابقه لــم يعثــر لــه علــى ســوابق جنائيــة مســجلة وحيــث إن مــا‬\n      ‫أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرعا اطلــب إثبــات‬\n      ‫مــا اســند إليــه واحلكــم بتعزيــره لقــاء ذلــك علمــا أنــه تنــازل عــن احلــق‬\n      ‫اخلــاص وهــو ســجني علــى ذمــة هــذه الدعــوى منــذ تاريــخ ‪1434/8/16‬‬\n      ‫ه ـ هــذه دعــواي وبســؤال املدعــى عليــه عمــا جــاء بدعــوى املدعــي العــام‬\n      ‫أجــاب وهــو ينطــق بالعربيــة قائــا مــا ذكــره املدعــي العــام يف دعــواه‬\n      ‫صحيــح جملــة وتفصيــا ففــي التاريــخ املذكــور يف الدعــوى دخلــت إلــى‬\n      ‫املنــزل املبــن أنفــا عــن طريــق بابــه اخلارجــي وكان مفتوحــا وقــد جــدت‬\n      ‫أهلــه نامــوا فســرقت منــه جهــازي جــوال نــوع نوكيــا كانــت علــى طاولــة‬\n      ‫بالقــرب مــن ســرير نــوم أحــد أهــل املنــزل كمــا وجــدت بنطــاال بالقــرب‬\n      ‫مــن أحــد النائمــن وكان فيــه مبلــغ وقــدره ســبعة وعشــرون ألــف ريــال‬\n      ‫فســرقت ذلــك املبلــغ ولــم يشــعر بــي أحــد ممــن كان باملنــزل املذكــور‬\n      ‫لكــون جميــع أبــواب غرفــه مفتوحــة وقــد تصرفــت يف بعــض املبلــغ‬\n      ‫املســروق وســلمت جــزء منــه إلــى اجلهــات األمنيــة كمــا ســلمتهم جهــازي‬\n      ‫اجلــوال و أنــا نــادم علــى فعلــي هــذا وتائــب هلل تعالــى هكــذا أجــاب هــذا‬\n      ‫وبالرجــوع إلــى املعاملــة وجــد بهــا تنــازل أصحــاب احلــق اخلــاص و إقرارهم‬\n\n\n‫‪363‬‬\n\f‫باســتالم جميــع حقوقهــم املســروقة فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة ومبــا أن املدعــى عليــه صــادق علــى دعــوى املدعــي العــام فأقــر‬\n‫بدخــول املنــزل املذكــور يف الدعــوى وســرقة املســروقات املبينــة آنفــا‬\n‫منــه ومبــا أن مــا أقــدم عليــه املدعــى عليــه اعتــداء آثــم و إخافــة للنــاس‬\n‫علــى أموالهــم و أخذهــا بالباطــل ومبــا أن الســرقة املذكــورة يف الدعــوى‬\n‫لــم تكــن مــن حــرز ومبــا أن هــذه اجلنايــة وقعــت يف بلــد اهلل احلــرام الــذي‬\n‫رفــع اهلل مكانــه وتوعــد بالعقــاب علــى مــن انتهــك محارمــه ومبــا أن‬\n‫التعزيــر يشــرع يف كل معصيــة ال حــد فيهــا وال كفــارة وهــو يختلــف‬\n‫باختــاف األحــوال واألشــخاص والزمــان واملــكان وتقديــر ذلــك راجــع‬\n‫لنظــر احلاكــم مبــا يــراه محققــا للزجــر والــردع جلميــع مــا ذكــر فقــد‬\n‫حكمــت بثبــوت إدانــة املدعــى عليــه مبــا نســب إليــه يف الدعــوى وقــررت‬\n‫تعزيــره علــى ذلــك بجلــد ألــف ومائتــي جلــدة تقــع علــى بدنــه علــى أربعــة‬\n‫وعشــرين دفعــة متســاوية وبــن كل دفعــة و أخــرى عشــرة أيــام ويســجن‬\n‫ســنة كاملــة ابتــداء مــن تاريــخ إيقافــه و أرى إبعــاده إلــى بلــده بعــد انتهــاء‬\n‫محكوميتــه و بعــد إنهــاء جميــع املطالبــات التــي لــه أو عليــه إن وجــدت‬\n‫وبعرضــه قــرر املدعــى عليــه قناعتــه باحلكــم أمــا املدعــي العــام قــرر‬\n‫عــدم القناعــة باحلكــم وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة‬\n‫إعتراضيــة فأجيــب لطلبــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/11/05‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ :‬ـ ـ نحــن رئيــس‬\n‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقــة‬\n‫مكــة املكرمــة جــرى منــا االطــاع على القــرار رقــم ‪34352474‬وتاريخ‬\n‫‪1434/11/6‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪.......... .‬القاضي باحملكمة‬\n\n\n                                                                                          ‫‪364‬‬\n\f      ‫اجلزائيــة باملدينــة املنــورة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪.......... /‬‬\n      ‫باكســتاني اجلنســية ‪ ،‬املتهــم يف قضيــة ســرقة‪ ،‬احملكــوم فيــه مبــا دون‬\n      ‫باطنــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه تقــرر باألكثريــة املوافقــة‬\n      ‫علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                      ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪365‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":360,"source_page_end":365,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4961046c1b694a0a41fdea53f84925862515fd16efe5a6e8de033d27aa17caef","normalized_text_hash":"6b13c3c6c429cba0617029bddb70c5468719aa7067daaa960c6cfe53098d82de","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p360-34352474"},{"id":"704b391c-f00a-5c95-8ce7-c8b22be08163","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -تقرير فني البصمات -ثبوت إدانة املدعى عليه -وجود سوابق قضائية -تقرير بالسجن واجللد -أخذ تعهد بعدم تكرار الفعل .","document_number":"34378220","case_number":"34540463","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/12/4","year":"1434","subject":"سرقة -سرقة سيارة -تقرير فني البصمات -ثبوت إدانة املدعى عليه -وجود سوابق قضائية -تقرير بالسجن واجللد -أخذ تعهد بعدم تكرار الفعل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 34378220 :‬تاريخه‪1434/12/4 :‬هـ‬\n                     ‫رقم الدعوى‪34540463:‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34387980‬تاريخه‪1434/12/25 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة ســيارة ‪ -‬تقريــر فنــي البصمــات ‪ -‬ثبــوت إدانــة املدعــى‬\n‫عليــه ‪ -‬وجــود ســوابق قضائيــة ‪ -‬تقريــر بالســجن واجللــد ‪ -‬أخــذ تعهــد‬\n                                                      ‫بعــدم تكــرار الفعــل ‪.‬‬\n\n\n\n\n           ‫(أن التعزير يشرع يف كل معصية ال حد فيها وال كفارة )‪.‬‬\n\n\n\n\n‫دعــوى املدعــي العــام ضــد املدعــى عليــه بســرقة ســيارة أثنــاء وقوفهــا‬\n‫بإحــدى املواقــف ويطلــب إثبــات إدانتــه وتعزيــره شــرعا‪ ،‬باالطــاع علــى‬\n‫البــاغ املقــدم مــن املجنــي عليــه عــن تعــرض ســيارته للســرقة لــم يجدهــا‬\n‫وأفــاد أن الســيارة كانــت مفتوحــة األبــواب مــن الداخــل وبالبحــث عــن‬\n‫الســيارة املذكــورة عثــر عليهــا وقــد صــدر تقريــر فنــي بصمــات مــن‬\n‫األدلــة اجلنائيــة املتضمــن انطبــاق بصمــة الكــف األيســر للمدعــى عليــه‬\n‫علــى األثــر املرفــوع مــن الســيارة املســروقة املشــار إليهــا وباســتجواب‬\n‫املدعــى عليــه ومواجهتــه بانطبــاق بصماتــه علــى البصمــات املرفوعــة‬\n‫مــن الســيارة املشــار إليهــا لــم يذكــر مــا يبــرر ســبب وجــود بصماتــه‬\n‫علــى تلــك الســيارة وجــرى مضاهــاة بصمــات املتهــم املذكــور علــى‬\n‫القضايــا املقيــدة ضــد مجهــول واتضــح انطباقهــا علــى اآلثــار املرفوعــة‬\n\n                                                                                   ‫‪366‬‬\n\f      ‫مــن حادثتــي الســرقة مــن محــل عطــور وحادثــة ســرقة مكينــة خياطــة‪،‬‬\n      ‫أقــر املدعــى عليــه مبــا جــاء يف الدعــوى‪ ،‬ثبــوت اإلدانــة وصــدر احلكــم‬\n      ‫بجلــده ســتمائة جلــدة تقــع علــى بدنــه علــى اثنتــي عشــرة دفعــة متســاوية‬\n      ‫وبــن كل دفعــة و أخــرى عشــرة أيــام‪ ،‬وســجنه ســنة كاملــة ابتــداء مــن‬\n      ‫تاريــخ إيقافــه‪ ،‬وأن يؤخــذ عليــه التعهــد بعــدم العــودة ملثــل ذلــك‪ ،‬وقــرر‬\n      ‫املدعــى العــام االعتــراض وطلــب االســتئناف بــدون الئحــة وقــرر املدعــى‬\n                   ‫عليــه القناعــة‪ ،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫باملدينة املنورة وبناء على املعاملة احملالة لنا من فضيلة رئيس احملكمة‬\n      ‫اجلزائيــة باملدينــة املنــورة برقــم ‪ 34540463‬وتاريــخ ‪1434/12/02‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 342742767‬وتاريــخ ‪ 1434/12/02‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافق‪1434/12/03‬ه ـ افتتحــت اجللســة الســاعة ‪: 00‬‬\n      ‫‪09‬وفيهاحضراملدعــي العــام يف هيئــة التحقيــق واالدعــاء العــام باملدينــة‬\n      ‫املنــورة ‪ ....‬وادعــى علــى احلاضــر معــه يف مجلــس احلكــم ‪ ....‬ســعودي‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ....‬قائــا يف حتريــر دعــواه إنــه باالطــاع‬\n      ‫علــى البــاغ املقــدم مــن املواطــن ‪ .... /‬عــن تعــرض ســيارته نــوع ‪.....‬‬\n      ‫حتمــل اللوحــة رقــم ( ‪ ).....‬للســرقة عندمــا قــام بإيقافهــا أمــام مقهــى‬\n      ‫‪ ...........‬وعنــد خروجــه مــن املقهــى عنــد الســاعة الثالثــة والنصــف فجــر ًا‬\n      ‫لــم يجدهــا وأفــاد أن الســيارة كانــت مفتوحــة األبــواب مــن الداخــل‬\n      ‫وبالبحــث عــن الســيارة املذكــورة عثــر عليهــا بتاريــخ ‪1434/02/22‬ه ـ‬\n      ‫وقــد صــدر تقريــر فنــي بصمــات رقــم ‪1434 /44‬ه ـ مــن قبــل األدلــة‬\n\n‫‪367‬‬\n\f‫اجلنائيــة املتضمــن انطبــاق بصمــة الكــف األيســر للمدعــى عليــه علــى‬\n‫األثــر املرفــوع مــن الســيارة املســروقة املشــار إليهــا وباســتجوابه املدعــى‬\n‫عليــه ومواجهتــه بانطبــاق بصماتــه علــى البصمــات املرفوعــة من الســيارة‬\n‫املشــار إليهــا لــم يذكــر مــا يبــرر ســبب وجــود بصماتــه علــى تلك الســيارة‬\n‫وجــرى مضاهــاة بصمــات املتهــم املذكــور علــى القضايــا املقيــدة ضــد‬\n‫مجهــول واتضــح انطباقهــا علــى اآلثــار املرفوعــة مــن حادثتــي الســرقة‬\n‫مــن محــل عطــور عائــد للمواطــن ‪ ....‬وحادثــة ســرقة مكينــة خياطــة‬\n‫عائــدة للمواطــن ‪ .....‬مبحافظــة ‪ .....‬وقــد جــرى مخاطبــة شــرطة ‪ .....‬برقــم‬\n‫‪ 24/11237/22‬وتاريــخ ‪1434/11/09‬ه ـ للتحقيــق مــع املذكــور بتلــك‬\n‫القضايــا وعالقتــه بهــا كمــا جــرى إشــعار شــرطة ‪ ......‬باخلطــاب رقــم‬\n‫‪ 24/7093/22‬وتاريــخ ‪1434/11/11‬ه ـ املتضمــن إحالــة املتهــم للســجن‬\n‫العــام علــى ذمــة قضيــة ســرقة الســيارة وتقــرر توجيــه االتهــام للمدعــى‬\n‫عليــه بســرقة ســيارة أثنــاء وقوفهــا مبواقــف مقهــى ‪ .......‬وذلــك لألدلــة‬\n                                                                 ‫والقرائــن التاليــة ‪:‬‬\n‫‪ / 1‬مــا جــاء مبحضــر الدوريــات األمنيــة املتضمــن العثــور علــى الســيارة‬\n‫املرفــق لفــة (‪ / 2 )2‬مــا جــاء بالتقريــر الفنــي بصمــات رقــم ‪1434/44‬ه ـ‬\n‫املرفــق لفــة (‪ )16‬ووردت نتيجــة البحــث يف ســجل املدعــى عليــه اجلنائــي‬\n‫وتبــن وجــود ســابقة مســجلة عليــه األولــى ســرقة اســطوانة غــاز و ســابقة‬\n‫ثانيــة يف حيــازة واســتعمال مخــدرات وحيــث إن مــا أقــدم عليــه املدعــى‬\n‫عليــه فعــل محــرم ومعاقــب عليــه شــرعا أطلــب إثبــات مــا نســب إليــه‬\n‫أعــاه واحلكــم عليــه بعقوبــة تعزيريــة رادعــة لــه زاجــرة لغيــره لقــاء ذلــك‬\n‫علمــا أن احلــق اخلــاص مــازال قائمــا وهــو ســجني علــى ذمــة هــذه القضيــة‬\n‫منــذ تاريــخ ‪1434/10/26‬ه ـ هــذه دعــواي وبســؤال املدعــى عليــه عمــا‬\n\n\n                                                                                          ‫‪368‬‬\n\f      ‫جــاء يف دعــوى املدعــي العــام أجــاب قائــا مــا ذكــره املدعــي العــام‬\n      ‫يف دعــواه صحيــح جملــة وتفصيــا ففــي التاريــخ املذكــور يف الدعــوى‬\n      ‫ســرقت الســيارة املبينــة آنفــا حيــث كانــت واقفــة يف املــكان املذكــور‬\n      ‫آنفــا وقــد كانــت مفتحــة أبوابهــا فقمــت بتشــغيلها بطريقتــي وقدتهــا‬\n      ‫وكان فيهــا بعــض األغــراض لــم آخــذ منهــا شــيئ ًا وقــد تركتهــا بعــد‬\n      ‫اســتعمالها يف مــكان بعيــد وقــد قبــض علـ ّـي رجــال األمــن بعــد خمســة‬\n      ‫أيــام مــن حادثــة الســرقة ومســجل علــي ســابقة يف ســرقة أســطوانة غــاز‬\n      ‫وثانيــة يف حيــازة واســتعمال مخــدرات وقــد نلــت العقــاب عليهــا جميعــا‬\n      ‫ولــم أســرق شــيئا غيــر الســيارة وأنــا نــادم علــى فعلــي هــذا هكــذا أجــاب‬\n      ‫عقــب ذلــك قــال املدعــي العــام إن املدعــى عليــه متهــم بســرقة محــل و‬\n      ‫ســرقة مكينــة خياطــة وقــد فصلــت لهــا أوراق مســتقلة فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه صــادق علــى دعــوى‬\n      ‫املدعــي العــام فأقــر بســرقة الســيارة املذكــورة يف الدعــوى ومبــا أن‬\n      ‫الشــرع قــد حــرم التعــدي علــى أمــوال النــاس احملترمــة املقومــة بغيــر‬\n      ‫حــق ومبــا أن مــا أقــدم عليــه املدعــى عليــه فيــه زعزعــة لألمــن وإخافــة‬\n      ‫للنــاس علــى أموالهــم ومبــا أن املدعــى عليــه مــن أربــاب الســوابق وقــد‬\n      ‫نــال العقــاب عليهــا ولــم يرتــدع وهــذا يؤكــد ســوء مســلكه ومبــا أن‬\n      ‫التعزيــر يشــرع يف كل معصيــة ال حــد فيهــا وال كفــارة وهــو يختلــف‬\n      ‫باختــاف األحــوال واألشــخاص والزمــان واملــكان وتقديــر ذلــك راجــع‬\n      ‫لنظــر احلاكــم مبــا يــراه محققــا للزجــر والــردع جلميــع مــا ذكــر فقــد‬\n      ‫حكمــت بثبــوت إدانــة املدعــى عليــه مبــا نســب إليــه يف الدعــوى وقــررت‬\n      ‫تعزيــره علــى ذلــك للحــق العــام بجلــده ســتمائة جلــدة تقــع علــى بدنــه‬\n      ‫علــى اثنتــي عشــرة دفعــة متســاوية وبــن كل دفعــة و أخــرى عشــرة أيــام‬\n\n\n‫‪369‬‬\n\f‫ويســجن ســنة كاملــة ابتــداء مــن تاريــخ إيقافــه ويؤخــذ عليــه التعهــد‬\n‫بعــدم العــودة ملثــل ذلــك وبعرضــه قــرر املدعــى عليــه قناعتــه باحلكــم أمــا‬\n‫املدعــي العــام فقــرر عــدم قناعتــه باحلكــم وطلــب رفعــه إلــى محكمــة‬\n‫االســتئناف بــدون الئحــة اعتراضيــة فأجيــب لطلبــه وقــد انتهــت اجللســة‬\n‫يف متــام الســاعة ‪0 9: 30‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                      ‫وعلــى آلــه وصحبــه وســلم حــرر يف‪1434/12/03‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة االســتئناف‬\n                                                                      ‫يف منطقــة‬\n‫مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 342742767‬وتاريــخ‬\n‫‪1434/12/3‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪.... /‬‬\n‫القاضــي باحملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪34378220‬‬\n‫وتاريــخ ‪1434/12/4‬ه ـ املتضمــن دعــوى املدعــي العــام ضــد‪، .... /‬‬\n‫املتهــم يف ســرقه مــن داخــل ســيارة احملكــوم فيــه مبــا دون باطــن القــرار‬\n‫‪.‬وبدراســة القــرار وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم واهلل‬\n‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،،،،،‬‬\n\n\n\n\n                                                                                      ‫‪370‬‬\n\f                        ‫كشاف املوضوعات‬\n\n‫الصفحة‬                      ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n          ‫دعوى عامة ضد أشخاص ‪ :‬األول والثاني خلعا‬\n  ‫‪5‬‬        ‫ماكينة صراف آلي وجراها بواسطة سيارة‬              ‫سرقة‬     ‫‪1‬‬\n         ‫ومحاولة سرقة ما بداخلها والثالث تستر عليهما‬\n\n\n          ‫دعوى عامة ضد أشخاص لتكوينهم عصابة‬\n  ‫‪14‬‬       ‫لسرقة السيارات ؛ حيث قاموا بتنفيذ عدة‬            ‫سرقة‬     ‫‪2‬‬\n                           ‫سرقات‬\n\n\n         ‫دعوى عامة ضد شخص النتهاكه حرمة منزل‬\n  ‫‪69‬‬     ‫بالدخول إليه بالقفز على السور اخللفي وسرقة‬         ‫سرقة‬     ‫‪3‬‬\n                   ‫بعض محتويات املنزل‬\n\n\n           ‫دعوى عامة ضد عدة أشخاص أحدهم بالغ‬\n  ‫‪75‬‬                                                        ‫سرقة‬     ‫‪4‬‬\n         ‫والباقون قصر بسرقة سيارتني والتفحيط عليها‬\n\n\n          ‫دعوى عامة ضد أشخاص لتكوينهم عصابة‬\n          ‫نشل يف املسجد احلرام فاألول ينشل من زوار‬\n  ‫‪85‬‬                                                        ‫سرقة‬     ‫‪5‬‬\n         ‫املسجد والثاني يستلم املسروق ويخفيه والثالث‬\n                     ‫يراقب ويغطي عليهما‬\n\n\n          ‫دعوى عامة ضد ‪ 9‬مواطنني اتهم الرابع بسرقة‬\n         ‫سيارة وبيعها وقام األول والثاني والثالث بشرائها‬\n ‫‪112‬‬         ‫وقيادتها واخلامس والسادس والسابع بدور‬          ‫سرقة‬     ‫‪6‬‬\n          ‫الوساطة يف البيع وحضورهم مع الثامن والتاسع‬\n                        ‫ملشاهدة التفحيط‬\n\f‫الصفحة‬                    ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة ضد ‪ 3‬أشخاص فاألول اشترك يف‬\n          ‫سرقة حمام من مزرعة وجهاز هاتف محمول‬\n ‫‪127‬‬                                                   ‫سرقة‬     ‫‪7‬‬\n         ‫والثاني والثالث قفزا إلى داخل عدة مزارع مع‬\n                    ‫االشتراك يف السرقة‬\n\n\n          ‫دعوى عامة ضد مقيم بطريقة غير مشروعة‬\n         ‫لسرقته إبل من حوش صاحب اإلبل الذي يعمل‬\n ‫‪139‬‬                                                   ‫سرقة‬     ‫‪8‬‬\n           ‫لديه مبشاركة راعي اإلبل وشخص ثالث‬\n                   ‫وانتحاله لشخصية الغير‬\n\n\n         ‫دعوى عامة ضد شخص لكسره زجاج سيارة‬\n ‫‪145‬‬     ‫وسرقة حقيبة حتتوي أوراقا رسمية وبطاقات‬        ‫سرقة‬     ‫‪9‬‬\n                         ‫أحوال‬\n\n\n           ‫دعوى عامة ضد شخص لشروعه يف سرقة‬\n ‫‪152‬‬                                                   ‫سرقة‬     ‫‪10‬‬\n                  ‫كيابل من موقع شركة‬\n\n\n         ‫دعوى عامة ضد شخصني اشتركا يف سرقة‬\n          ‫أسالك نحاسية من مستودع بعد هتك احلرز‬\n ‫‪156‬‬                                                   ‫سرقة‬     ‫‪11‬‬\n          ‫والتستر مع شريكهما واشتراك الثاني يف‬\n                       ‫سرقة استراحة‬\n\n\n         ‫دعوى عامة ضد شخص باالشتراك مع هارب‬\n         ‫يف تكوين عصابة لسرقة السيارات وأجزائها‬\n ‫‪166‬‬                                                   ‫سرقة‬     ‫‪12‬‬\n           ‫واستغالل عمله يف الورشة لتحريف أرقام‬\n            ‫الهياكل وتركيبها على سيارات أخرى‬\n\n\n         ‫دعوى عامة ضد مواطن لسرقته سيارة وإحداث‬\n ‫‪183‬‬      ‫تلفيات بها والتصرف مبا كانت حتتويه من‬        ‫سرقة‬     ‫‪13‬‬\n                          ‫بضاعة‬\n\f‫الصفحة‬                    ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n          ‫دعوى عامة ضد مقيم يعمل يف ورشة لسرقته‬\n ‫‪193‬‬       ‫سيارتني ولوحة سيارة مبشاركة أشخاص‬            ‫سرقة‬     ‫‪14‬‬\n                    ‫آخرين تستر عليهم‬\n\n\n          ‫دعوى عامة ضد شخص ملشاركته يف سرقة‬\n ‫‪199‬‬                                                    ‫سرقة‬     ‫‪15‬‬\n               ‫مسجالت وسماعات من سيارات‬\n\n\n           ‫دعوى عامة ضد خمسة أشخاص يحملون‬\n ‫‪204‬‬       ‫بطاقات بديلة لسرقتهم مجموعة أغنام من‬         ‫سرقة‬     ‫‪16‬‬\n                         ‫حظيرة‬\n\n\n         ‫دعوى عامة ضد ثالثة أشخاص بتهمة االشتراك‬\n ‫‪211‬‬         ‫يف سرقة سيارة والتجول بها وإخفائها‬         ‫سرقة‬     ‫‪17‬‬\n                       ‫والتخطيط لذلك‬\n\n\n           ‫دعوى عامة ضد شخصني يحمالن بطاقتني‬\n           ‫بديلتني يف استالم سيارة من شخص لغرض‬\n ‫‪222‬‬                                                    ‫سرقة‬     ‫‪18‬‬\n          ‫تغسيلها فتركاها أمام املغسلة مما تسبب يف‬\n                          ‫سرقتها‬\n\n\n         ‫دعوى عامة ضد أشخاص فاألول والثاني اختلسا‬\n           ‫مبلغا ماليا من حساب عميل دون علمه واتهام‬\n ‫‪228‬‬      ‫الثالث والرابع واخلامس والسادس بإعطاء حرية‬    ‫سرقة‬     ‫‪19‬‬\n          ‫التصرف لألول بحساباتهم الشخصية مما سهل‬\n                           ‫االختالس‬\n\n\n           ‫دعوى عامة ضد شخص لسرقته طيرا من‬\n ‫‪256‬‬       ‫القفص من محل بيع طيور وإخفائه حتت‬            ‫سرقة‬     ‫‪20‬‬\n                         ‫مالبسه‬\n\f‫الصفحة‬                   ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة ضد مقيم لسرقته سيارة من أمام‬\n ‫‪261‬‬                                                  ‫سرقة‬     ‫‪21‬‬\n              ‫إحدى املطاعم وهي بوضع التشغيل‬\n\n\n          ‫دعوى عامة ضد أربعة أشخاص لتكوينهم‬\n ‫‪265‬‬       ‫عصابة سرقة من املعتمرين يف األماكن‬         ‫سرقة‬     ‫‪22‬‬\n                        ‫املزدحمة‬\n\n\n            ‫دعوى عامة ضد شخص لتكسيره زجاج‬\n ‫‪273‬‬     ‫سيارات وسرقة أربعة مسجالت فيها وكاميرا‬       ‫سرقة‬     ‫‪23‬‬\n                        ‫تلفزيونية‬\n\n\n          ‫دعوى عامة ضد شخص من أرباب السوابق‬\n ‫‪282‬‬                                                  ‫سرقة‬     ‫‪24‬‬\n           ‫بسرقة سيارة متوقفة أمام منزل صاحبها‬\n\n\n         ‫دعوى عامة ضد أربعة أشخاص فاألول سرق‬\n         ‫سيارة وتصرف بها بتشليحها واشتراك الثاني‬\n ‫‪286‬‬                                                  ‫سرقة‬     ‫‪25‬‬\n         ‫والثالث يف تشليحها وتسترهما مع الرابع على‬\n                           ‫األول‬\n\n\n         ‫دعوى عامة ضد شخص لسرقته من منزل جاره‬\n ‫‪294‬‬      ‫ومحاولة تضليل جهة التحقيق بادعاء تعرضه‬      ‫سرقة‬     ‫‪26‬‬\n                        ‫لسرقة جواله‬\n\n\n         ‫دعوى عامة ضد شخص لسلبه سيارة شخص‬\n ‫‪299‬‬                                                  ‫سرقة‬     ‫‪27‬‬\n                      ‫والفرار بها‬\n\n\n         ‫دعوى عامة ضد شخص حملاولته كسر الباب‬\n ‫‪303‬‬                                                  ‫سرقة‬     ‫‪28‬‬\n            ‫اخلارجي إلحدى األسواق بقصد سرقته‬\n\f‫الصفحة‬                     ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n          ‫قدم شيكا‬ ‫دعوى عامة ضد أشخاص فاألول ّ‬\n ‫‪310‬‬     ‫مزورا إلحدى املؤسسات والثاني حليازة وبيع عدد‬    ‫سرقة‬     ‫‪29‬‬\n            ‫أربع سبائك ذهب والثالث خليانة األمانة‬\n\n\n         ‫دعوى عامة ضد شخص الشتراكه مع آخر يف‬\n ‫‪326‬‬                                                     ‫سرقة‬     ‫‪30‬‬\n                     ‫نشل حقيبة امرأة‬\n\n\n         ‫دعوى عامة ضد شخص يعمل خفيرا لتمكينه‬\n ‫‪331‬‬     ‫شخص ًا من سرقة ماكينة واسطة بحرية تابعة‬         ‫سرقة‬     ‫‪31‬‬\n                  ‫حلرس احلدود مقابل مبلغ مالي‬\n\n\n          ‫دعوى عامة ضد شخص لقيامه بسرقة أموال‬\n ‫‪337‬‬                                                     ‫سرقة‬     ‫‪32‬‬\n                  ‫وأجهزة وغيرها من شركة‬\n\n\n         ‫دعوى عامة ضد شخص يعمل مسؤول صندوق‬\n ‫‪349‬‬                                                     ‫سرقة‬     ‫‪33‬‬\n             ‫باختالس مبلغ مالي من خزنة مجمع‬\n\n\n          ‫دعوى عامة ضد شخص لسرقته حافظة نقود‬\n ‫‪355‬‬                                                     ‫سرقة‬     ‫‪34‬‬\n                         ‫من سيارة‬\n\n\n          ‫دعوى عامة ضد شخص لدخوله منزال وسرقة‬\n ‫‪360‬‬                                                     ‫سرقة‬     ‫‪35‬‬\n                 ‫مبلغ مالي منه وجهازي جوال‬\n\n\n          ‫دعوى عامة ضد شخص لسرقته سيارة أثناء‬\n ‫‪366‬‬                                                     ‫سرقة‬     ‫‪36‬‬\n                     ‫وقوفها بإحدى املواقف‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":366,"source_page_end":375,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"70e4598fa01906196247b4b811651f2095fedb44f8e1f8c1dcc1aef15973e75d","normalized_text_hash":"4b81b7ab4386e3b059d3be60652fbf7dd9d79a698a096e52a8d27a8b5290d80c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p366-34378220"},{"id":"70de9b95-c505-56cd-8153-87d39aa79b57","document_type":"judgment","category":"judicial","subcategory":"general","title":"خيانة أمانة -عجز يف عهدة العامل -إنكار الدعوى -صرف النظر عن دعوى املدعي العام لعدم ثبوتها.","document_number":"34312068","case_number":"4579","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/09/03","year":"1434","subject":"خيانة أمانة -عجز يف عهدة العامل -إنكار الدعوى -صرف النظر عن دعوى املدعي العام لعدم ثبوتها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫رقم الصك‪ 34312068 :‬تاريخه‪1434/09/03 :‬هـ‬\n                            ‫رقم الدعوى‪4579 :‬‬\n           ‫قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34356932‬تاريخه‪1434/11/11 :‬هـ‬\n\n\n     ‫خيانــة أمانــة ‪ -‬عجــز يف عهــدة العامــل ‪ -‬إنــكار الدعــوى ‪ -‬صــرف النظــر‬\n                                          ‫عــن دعــوى املدعــي العــام لعــدم ثبوتهــا‪.‬‬\n\n\n\n\n                                        ‫ما أشار إليه القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n           ‫تقــدم ملركــز الشــرطة وكيــلٌ شــرعي إلحــدى املؤسســات ببـ ٍ‬\n     ‫ـاغ عــن‬\n     ‫مكفــول املؤسســة (املدعــى عليــه) مفــاده أنــه خــان األمانــة‪ ،‬وقــام بأخــذ‬\n     ‫مبلــغ مالــي أثنــاء عملــه مندوبــا للمبيعــات يف املؤسســة ‪ ،‬بالتحقيــق مــع‬\n     ‫املدعــى عليــه اعتــرف بوجــود العجــز لديــه باملبلــغ املشــار إليــه مــن خــال‬\n     ‫بيعــه للبضائــع يف احملــات وأنــه املســؤول عن ذلك املبلــغ وصدق اعترافه‬\n     ‫شــرعا ‪ ،‬مت توجيــه االتهــام لــه بخيانــة األمانــة ‪ ،‬بالبحــث عــن ســوابقه‬\n     ‫لــم يعثــر لــه علــى ســوابق مســجلة ‪ ،‬طلــب املدعــى العــام احلكــم عليــه‬\n     ‫بعقوبــة تعزيريــة لقــاء خيانتــه لألمانــة ‪ .‬بعــرض ذلــك علــى املدعــي عليــه‬\n     ‫أنكــر اخليانــة‪ ،‬وأفــاد أن ســبب هــذا العجــز أنــه اســتلم مــن املؤسســة‬\n     ‫مــواد غذائيــة وقــام بتصريفهــا باألجــل ويأخــذ علــى ذلــك عمولــة ورمبــا‬\n     ‫بــاع بأقــل مــن القيمــة ألجــل العمولــة فحصــل العجــز وأنــه صــدر حكـ ٌـم‬\n     ‫يف احلــق اخلــاص ُيلزمــه بتســليم املبلــغ ‪ ،‬جــرى االطــاع علــى صــك احلكم‬\n‫‪5‬‬\n\f‫يف احلــق اخلــاص ‪ ،‬كمــا جــرى االطــاع علــى إقرار املدعــى عليه املصدق‬\n‫عليــه شــرعا ‪ ،‬نظــر ًا إلــى أن إقــرار املدعــى عليــه وجوابــه ليــس فيــه مــا‬\n‫يثبــت إدانتــه مبــا اتهــم بــه مــن االختــاس وخيانــة األمانــة لــذا مت احلكــم‬\n‫بصــرف النظــر عــن دعــوى املدعــي العــام لعــدم ثبوتهــا ‪ ،‬بعــرض احلكــم‬\n‫علــى الطرفــن قــرر املدعــي العــام عــدم القناعــة وطلــب رفــع احلكــم‬\n‫إلــى محكمــة االســتئناف مكتفيــا بالئحــة الدعــوى العامــة وبعــد رفــع‬\n                        ‫احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 4579‬وتاريــخ ‪ 1431/02/15‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 3114570‬وتاريــخ ‪ 1431/02/15‬ه ـ ففــي يــوم‬\n‫اخلميــس املوافــق‪ 1434/09/03‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 45‬‬\n‫وفيهــا حضــر ‪ ...‬وقــال بصفتــي مدعيــا عامــا بدائــرة االدعــاء العــام بدائرة‬\n‫الريــاض ادعــي ‪ 56 ...‬ســنة مينــي اجلنســية يحمــل إقامــة رقــم ‪ ...‬موقــف مــن‬\n‫تاريــخ ‪1431/1/9‬ه ـ حيــث أنــه بتاريــخ ‪1430/11/15‬ه ـ تقــدم مركــز‬\n‫شــرطة العزيزيــة وكيــل شــرعي ملؤسســة ‪ ...‬ببــاغ عــن مكفولهــم‬\n‫املذكــور أنــه خــان األمانــة وقــام باختــاس مبلــغ قــدره ثالثمئــة واربعــة‬\n‫وعشــر ألــف وخمســمئة وســتون ريــال حيــث يعمــل يف املؤسســة مندوبــا‬\n‫للمبيعــات وقــدم للوكيــل الشــرعي تقريــر ًا مــن محاســب قانونــي يثبــت‬\n‫ذلــك وبالتحقيــق معــه اعتــرف بوجــود العجــز لديــه باملبلــغ املشــار إليــه‬\n‫مــن خــال بيعــه للبضائــع يف احملــات وأنــه املســؤول عــن ذلــك املبلــغ‬\n\n                                                                                       ‫‪6‬‬\n\f    ‫وصــدق اعترافــه شــرعا وقــد أســفر التحقيــق عــن توجيــه االتهــام لــه‬\n    ‫بخيانــة األمانــة لوجــود عجــز مبلــغ مالــي قــدره ثالثمئــة واربعــة وعشــر‬\n    ‫ألــف وخمســمئة وســتون ريــال وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى‬\n    ‫ســوابق مســجلة وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب‬\n    ‫عليــه لــذا أطلــب احلكــم عليــه بعقوبــة تعزيريــة لقــاء مــا أســند إليــه علمــا‬\n    ‫بــأن احلــق اخلــاص مــا زال قائمــا وبــاهلل التوفيــق هــذا وقــد حضــر املدعــى‬\n    ‫عليــه ‪ ....‬معــه بطاقــة نزيــل برقــم ‪2/31/92‬س صــادرة مــن مديــر ســجن‬\n    ‫امللــز وجــرى عــرض الئحــة املدعــي العــام ضــده عليــه فأجــاب قائــا قــد‬\n    ‫صــدر علــي حكــم مــن احملكمــة العامة بدفع مبلغ قــدره ثالثمئة وأربعة‬\n    ‫عشــر ألــف وخمســمئة وواحــد وســتون ريــاال وذلــك لصالــح املؤسســة التي‬\n    ‫كنــت أعمــل فيهــا وهــي مؤسســة ‪ ...‬وكان ســبب هــذا املبلغ أنني أســتلم‬\n    ‫مــن املؤسســة مــواد غذائيــة حلــوم مجمــدة وخضــار وأقــوم بتصريفهــا‬\n    ‫باألجــل ثــم بعــد ذلــك حصــل عنــدي عجــز مالــي نتيجــة أن اســتالمي مــن‬\n    ‫املؤسســة باحلــال وتصريفــي لهــا يكــون باآلجــل وآخــذ علــى ذلــك عمولــة‬\n    ‫مــن املؤسســة فكنــت أســتعجل البيــع باآلجــل رمبــا كان مببلــغ أقــل‬\n    ‫مــن أجــل العمولــة ثــم قــال أنــا موقــف علــى ذمــة تســديد هــذا املبلــغ الــذي‬\n    ‫حكمــه بــه علــي قبــل نحــو ثــاث ســنوات ثــم جــرى تصفــح أوراق املعاملــة‬\n    ‫فوجــدت مــن ضمنهــا احلكــم الصــادر مــن احملكمــة العامــة بالريــاض‬\n    ‫علــى املدعــى عليــه بدفــع املبلــغ املذكــور لصالــح مؤسســة ‪ ...‬وهــو برقــم‬\n    ‫‪ 32232057‬بتاريــخ ‪1432/9/7‬ه ـ وقــد ورد بدعــوى باحلــق اخلــاص علــى‬\n    ‫املدعــى عليــه مــا نصــه (إن املدعــى عليــه يعمــل لــدى موكلــي بوظيفــة‬\n    ‫منــدوب مبيعــات وقــد اتضــح أن لديــه عجــز مالــي وقــدره ثالثمئــة وواحــد‬\n    ‫وعشــرون ألــف وخمســمئة وواحــد وســبعون ريــاال) أ‪.‬ه ـ فكانــت اإلجابــة‬\n\n\n‫‪7‬‬\n\f‫املصادقــة علــى ذلــك بعــد تعديــل املبلــغ ثــم انتهــى النظــر الشــرعي بإلــزام‬\n‫املدعــى عليــه بدفــع املبلــغ املذكــور وقــد اكتســب احلكــم القطعيــة‬\n‫بقناعــة الطرفــن ثــم جــرى ســؤال املدعــي العــام عــن بينته فقــال اعتراف‬\n‫املدعــى عليــه املصــدق شــرعا يف الصحيفــة رقــم ‪ 15‬مــن ملــف التحقيــق‬\n‫املرفــق باملعاملــة وباالطــاع عليــه ألفيــت نصــه (نعــم أنــا ‪ ...‬مينــي اجلنســية‬\n‫‪ 51‬عامــا أنــه أثنــاء عملــي مبؤسســة ‪ ...‬التجاريــة كمنــدوب مبيعــات‬\n‫اتضــح أنــه يوجــد يف ذمتــي مبلــغ مالــي وقــدره ثالثمئــة وأربعــة عشــر ألــف‬\n‫وخمســمئة وواحــد وســتون ريــال وهــي قيمــة بضائــع تبــاع بقيمــة آجــل‬\n‫الدفــع بعــد دفعهــا وبيعهــا وهــي حتــت مســؤوليتي ويف ذمتــي هــذا إقراري‬\n‫) وقــد صــدق هــذا اإلقــرار مــن قبــل فضيلــة رئيــس احملكمــة بتاريــخ‬\n‫‪1431/1/11‬ه ـ ثــم قــال املدعــي العــام بينتــي الثانيــة يف تقريــر احملاســب‬\n‫القانونــي ثــم جــرى تصفــح أوراق املعاملــة فلــم أجــد مــن ضمنهــا هــذا‬\n‫التقريــر وســألت املدعــي العــام عنــه فقــال ليــس لــدي غيــر مــا يف أوراق‬\n‫املعاملــة ثــم جــرى ســؤال املدعــى عليــه فقــال ليــس لــدي غيــر مــا قلــت‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث إن التقاريــر الســابقة‬\n‫الصــادرة مــن املدعــى عليــه املتمثلــة يف إقــراره املصــدق شــرع ًا املرصــود‬\n‫بعاليــه وكــذا الدعــوى باحلــق اخلــاص عليــه مــع إقــراره هــذا اليــوم لدينــا‬\n‫إنــه ليــس يف ذلــك مــا يثبــت إدانتــه مبــا أتهــم بــه مــن االختــاس وخيانــة‬\n‫األمانــة بــل الغايــة ومــا فيهــا عجــز مالــي أثنــاء العمــل لــذا فقــد صرفــت‬\n‫النظــر عــن طلــب املدعــي العــام وبذلــك حكمــت وبتــاوة احلكــم علــى‬\n‫الطرفــن قــرر املدعــي العــام عــدم القناعــة وطلــب رفــع احلكــم إلــى‬\n‫محكمــة االســتئناف مكتفيــا بالئحــة الدعــوى العامــة واقفــل احملضــر‬\n‫الســاعة ‪ 12.45‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n\n\n                                                                                         ‫‪8‬‬\n\f                                    ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/9/3‬ه ـ‬\n    ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n    ‫األولــى مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n    ‫رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪ 341992022‬وتاريــخ‬\n    ‫‪1434/10/22‬ه ـ واملرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n    ‫باحملكمــة‪ ... /‬برقــم ‪ 34312068‬وتاريــخ ‪1434/9/3‬ه ـ واخلــاص‬\n    ‫بدعــوى املدعــي العــام ضــد‪»... /‬مينــي اجلنســية»‪ ،‬وموضوعهــا قضيــة‬\n    ‫خيانــة أمانــة وانتهــاء الدراســة والتدقيــق املصادقــة علــى احلكــم لعــدم‬\n    ‫موجــب املالحظــة مــع تنبيــه فضيلتــه إلــى تدويــن كلمــة (ابــن) يف اســم‬\n    ‫فضيلتــه يف بــدء القــرار ويف ختامــه ‪،‬ورصــد اســم املدعــي العــام الثالثــي‬\n    ‫حتــت توقيعــه يف الضبــط حســب التعليمــات وتصحيــح األخطــاء املعلــم‬\n    ‫ال واهلل املوفــق وصلــى‬ ‫عليهــا بقلــم الرصــاص ومالحظــة ذلــك مســتقب ً‬\n                    ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــة وســلم ‪.‬‬\n\n\n\n\n‫‪9‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":5,"source_page_end":9,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5f4618e6b6fcfb1ae956a228be5fd138be05ca9d0156e43ff555cd968c1c4254","normalized_text_hash":"07989f4c63758b3c46fd15eff6db7439569e62b0ac9d38304c44781e425a604b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p5-34312068"},{"id":"b64ea314-84ce-5016-b73b-15788b1aae39","document_type":"judgment","category":"judicial","subcategory":"general","title":"خيانة أمانة -أخذ املدعى عليه عليهما مبلغ مالي من الشركة التي يعمان بها -إقرار -إثبات إدانة بخيانة األمانة -تغليظ العقوبة -التعزير بالسجن واجللد .","document_number":"34227186","case_number":"3455426","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/29","year":"1434","subject":"خيانة أمانة -أخذ املدعى عليه عليهما مبلغ مالي من الشركة التي يعمان بها -إقرار -إثبات إدانة بخيانة األمانة -تغليظ العقوبة -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34227186 :‬تاريخه‪1434/5/29 :‬هـ‬\n                    ‫رقم الدعوى‪3455426 :‬‬\n       ‫قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34263495‬تاريخه‪1434/7/9:‬هـ‬\n\n\n‫خيانــة أمانــة ‪ -‬أخــذ املدعــى عليــه عليهمــا مبلــغ مالــي مــن الشــركة‬\n‫التــي يعمــان بهــا ‪ -‬إقــرار ‪ -‬إثبــات إدانــة بخيانــة األمانــة ‪ -‬تغليــظ‬\n                                ‫العقوبــة ‪ -‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n    ‫‪ -‬قول اهلل تعالى‪( :‬إن اهلل يأمركم أن تؤدوا األمانات إلى أهلها) ‪.‬‬\n\n\n\n\n‫توجيــه االتهــام للمدعــى عليهمــا بخيانــة األمانــة وأخــذ مبلــغ مالــي مــن‬\n‫الشــركة التــي يعمــان فيهــا ‪ -‬بالبحــث عــن ســوابقهما لــم يعثــر لهمــا‬\n‫على سوابق‪ -‬طلب املدعي العام إثبات ما أسند إليهما واحلكم عليهما‬\n‫بعقوبــة تعزيريــة ‪ -‬بعــرض دعــوى املدعــي العــام علــى املدعــى عليهمــا أقــر‬\n‫ا ومعقب ـ ًا يف الشــركة املدعيــة باحلــق اخلــاص‬    ‫األول أنــه يعمــل مراس ـ ً‬\n‫وأنــه أخــذ مــن أموالهــا ســتني ألــف ريــال وأخفاهــا وأنــه ليــس للمدعــى‬\n‫عليــه الثانــي أي عالقــة يف أخــذ أمــوال الشــركة‪ ،‬وأجــاب املدعــى عليــه‬\n‫الثانــي أنــه يعمــل يف الشــركة املدعيــة باحلــق اخلــاص مراســا وليــس لــه‬\n‫عالقــة باختــاس األمــوال ‪ -‬جــرى االطــاع علــى أقــوال املدعــى عليــه‬\n‫الثانــي حتقيق ـاً‪ ،‬وعلــى إقــراره املصــدق شــرعا‪ ،‬وبعرضــه عليــه ذكــر‬\n‫أنــه وقــع عليــه دون أن يقــرأه وصــادق عليهــا‪ -‬نظــر ًا إلقــرار املدعــى عليــه‬\n                                                                                       ‫‪10‬‬\n\f     ‫األول مبــا جــاء يف الدعــوى وإقــرار املدعــى عليــه الثانــي بأخــذه مبلــغ‬\n     ‫ســتني ألــف ريــال مــن أمــوال الشــركة وأنــه هــو املبلــغ الوحيــد الــذي‬\n     ‫ســحبه منهــا لوجــود حســاب خــاص بالشــركة وإلقــرار املدعــى عليــه‬\n     ‫الثانــي بإرجاعــه املبلــغ يف يــوم احلادثــة ولظهــور اخليانــة بتصــرف املدعــى‬\n     ‫عليهمــا املذكــور ومشــروعية التعزيــر عليــه ‪ ،‬لــذا ثبتــت إدانــة املدعــى‬\n     ‫عليهمــا بخيانــة األمانــة وأخــذ مبلــغ مالــي مــن الشــركة ومت احلكــم‬\n     ‫عليهمــا مبــا يلــي ‪ /1 :‬ســجن املدعــى عليــه األول ثالثــون شــهرا وجلــده‬\n     ‫ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات ‪ /2‬ســجن املدعــى عليــه الثانــي‬\n     ‫ســنة وجلــده مائــة وعشــرين جلــدة مفرقــة علــى دفعتــن كل دفعــة ســتون‬\n     ‫جلــدة واجللــد أمــام النــاس ‪ -‬بعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n     ‫عليهمــا القناعــة وقــرر املدعــي العــام االعتــراض مكتفيــا بالئحــة‬\n     ‫الدعــوى‪ ،‬وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزائيــة بالريــاض برقــم ‪ 3455426‬وتاريــخ ‪ 1434/02/03‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 34275988‬وتاريــخ ‪ 1434/02/03‬ه ـ ففــي يــوم‬\n     ‫الســبت املوافق‪ 1434/03/14‬هـ افتتحت اجللســة الســاعة ‪10 : 00‬وفيها‬\n                   ‫قــدم املدعــي العــام ‪.....‬الئحــة دعــوى عامــة ضــد كل مــن ‪/‬‬\n     ‫‪ 26..... .1‬ســنة ســعودي اجلنســية ســجل مدني رقم (‪ ).....‬موقوف مبوجب‬\n                          ‫مذكرة التوقيف رقم (‪ ).....‬وتاريخ‪1433/11/28‬هـ ‪.‬‬\n     ‫‪ 25..... .2‬ســنة ميانــي اجلنســية مبوجــب رخصــة اإلقامة رقــم (‪ ).....‬موقوف‬\n‫‪11‬‬\n\f                 ‫مبوجب مذكر ة توقيف رقم (‪.....‬وتاريخ‪1433/11/28‬هـ ‪.‬‬\n‫بتاريــخ ‪1433/10/28‬ه ـ حضــر ملركــز شــرطة ‪.....‬األول مبلغ ـ ًا بانــه‬\n‫أثنــاء خروجــه مــن مكتــب فــرع ‪.....‬للتأمــن والــذي يعمــل بهــا بحــي‬\n‫‪.....‬علــى ســيارته مــن نــوع ‪ ......‬ومعــه ظــرف أبيــض بداخلــه مبلــغ مالــي‬\n‫وقــدره (‪ )144710‬مائــة وأربعــة وأربعــون ألــف وســبعمائة وعشــرة‬\n‫ريــاالت وشــيكني األول صــادر مــن البنــك ‪ ..........‬بقيمــة (‪ )15728‬ريــال‬\n‫والثانــي شــيك مــن البنــك ‪ ...........‬بقيمــة (‪ )10726‬ريــال وعنــد وصولــه‬\n‫إلــى شــارع ‪ .....‬مــع طريــق ‪ .....‬وأمــام مطعــم ‪ .....‬قــام صاحــب ســيارة مــن‬\n‫نــوع كابــرس اللــون أســود مظللــة بالكامــل (ال يعــرف رقــم اللوحــة)‬\n‫بالتوقــف خلفــه وأثنــاء ذلــك نــزل شــخص أســود البشــرة بكســر زجــاج‬\n‫ســيارة املبلــغ وضربــه مبفــك علــى يــده اليســرى ونــزل صاحــب الســيارة‬\n‫‪ .......‬وهــو اســود البشــرة وقــام بفتــح بــاب الراكــب وأخــذ الظــرف مــن‬\n‫حتــت املرتبــة األولــى والهــرب علــى الســيارة وقيــام األخــر بالهــرب مــع‬\n‫صاحــب الســيارة الكابــرس و ادعــى أنــه قــام مبالحقتهــم حتــى الوصول‬\n‫حلــي ‪.....‬ولــم يتمكــن مــن القبــض عليهــم ونتــج عــن ذلــك إصابتــه بجــرح‬\n‫يف الســاعد األيســر ‪.‬ولعــدم قناعــة جهــة التحقيــق يف صحــة البــاغ (مت‬\n‫التحفــظ علــى املبلــغ يف حينــه) واعتــرف علــى زميلــه الثانــي والــذي مت‬\n                            ‫القبــض عليــه مــن قبــل وحــدة البحــث باملركــز ‪.‬‬\n‫وجــرى االنتقــال رفــق األول الســتراحته الواقعــة بحي ‪.....‬وقام باســتخراج‬\n‫مبلــغ (‪ )858536‬خمســة وثمانــون ألــف وخمســمائة وســتة وثالثــون ريــال‬\n   ‫والشــيكان التــي قــام بســرقتها والعائــدة لشــركة الــذي يعملــون بهــا ‪.‬‬\n‫وبضبط إفادة ‪..... /‬أفاد بأنه جرى تسليم األول مبلغ وقدره (‪)144710‬‬\n‫مائــة وأربعــة وأربعــون ألــف وســبعمائة وعشــرة ريــاالت وشــيكان تخــص‬\n\n\n                                                                                      ‫‪12‬‬\n\f     ‫‪.....‬لتأمــن ولــم يقــم بإيداعهــا وأنــه مــن املفتــرض قيامــه بالذهــاب رفــق‬\n     ‫الثانــي وقــد طلــب مــن زميلــه عــدم مرافقتــه حســب أفادتــه وقــد تأخــر يف‬\n                                                      ‫بالغــه ويشــك يف صحــة بالغــه ‪.‬‬\n     ‫وباســتجواب األول أعتــرف أن جميــع مــا ذكــره غيــر صحيــح وأنــه‬\n     ‫أختلــق تلــك القصــة لســرقة املبلــغ حيــث أقــر بقيامــه باســتالم املبلــغ‬\n     ‫وطلــب مــن زميلــه الثانــي عــدم مرافقتــه وقــام بالذهــاب إلــى اســتراحة‬\n     ‫بحــي ‪.....‬وإخفــاء املبلــغ والشــيكان املســروقة والتمثيــل بكســر زجــاج‬\n     ‫ســيارته أمــام االســتراحة والذهــاب إلــى حــي ‪.....‬ومقابلــة زميلــه الثانــي‬\n     ‫وتســليمه مبلــغ ســتون ألــف ريــال مــن املبلــغ الــذي أخــذه مــن الشــركة‬\n     ‫وأضــاف انــه اجتــه ملركــز الشــرطة لتقــدمي بــاغ كاذب ‪.‬وباســتجواب‬\n     ‫الثانــي ذكــر بأنــه خــرج مــع زميلــه األول مــن الشــركة بعــد اســتالمه‬\n     ‫مبلــغ وقــدره (‪ )144710‬مائــة وأربعــة وأربعــون ألــف وســبعمائة وعشــرة‬\n     ‫ريــاالت وشــيكان عائــدة للشــركة لغــرض إيداعهــا وعندهــا طلــب منــه‬\n     ‫زميلــه األول أن ال يرافقــه للبنــك وذهــب لوحــده لبنــك ‪ ...........‬إليــداع‬\n     ‫مبالــغ ماليــة وبعــد خروجــه مــن البنــك ‪ ...........‬قــام باالتصــال علــى زميلــه‬\n     ‫األول علــى هاتفــه وأفــاد بأنــه يطــارده أشــخاص قامــوا بســرقته وقابلــه‬\n     ‫بحــي ‪.....‬وذكــر لــه احلادثــة وقــام بــدوره بإبــاغ دوريــات األمــن وأنــه ليــس‬\n     ‫لديــه مــا يضيفــه (وبعــد اعتــراف زميلــه بتســليمه مبلــغ ســتون ألــف ريــال‬\n     ‫مــن املبلــغ املســروق) اعتــرف مبقابلــة األول واســتالم منــه مبلــغ ســتون‬\n     ‫ألــف ريــال والتــي ســبق وأن أخذهــا مــن الشــركة وأعطــاه لــه وأضــاف‬\n     ‫بــأن الشــركة قامــت بطلــب املبلــغ منــه بنفــس يــوم احلادثــة (ممــا يؤكــد‬\n     ‫أنــه خطــط مــع زميلــه املدعــى عليــه األول) وقــام بطلــب املبلــغ مــن زميلــه‬\n     ‫والــذي قــام بتســليم املبلــغ لــه ومــن ثــم قــام هــو بــدوره بإعادتــه لشــركة‪.‬‬\n\n\n‫‪13‬‬\n\f‫)مت معاجلــة موضــوع البــاغ الــكاذب مــن قبــل اجلهــة املختصــة(‪ .‬وقــد‬\n‫أســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليهمــا بخيانــة األمانــة‬\n                       ‫وأخــذ مبلــغ مالــي وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n‫‪ /1‬اعتــراف األول والثانــي املــدون صفحــة (‪ )14.8‬مــن دفتــر التحقيــق‬\n                                                            ‫املرفــق داخــل الطــرد‬\n‫‪ /2‬محضــر االنتقــال واملعاينــة علــى مــكان املبالــغ والشــيكات املرفــق‬\n                                             ‫‪.‬‬                       ‫داخــل الطــرد‬\n                  ‫‪ /3‬إفادة ‪ ..... /‬واملدون يف دفتر التحقيق املرفق بالطرد ‪.‬‬\n                                 ‫وببحث سوابقهما لم يعثر لهما على سوابق ‪.‬‬\n‫وحيــث أن مــا أقــدم عليــه املدعــى عليهمــا فعــل محــرم ومعاقــب عليــه‬\n‫شــرعا أطلــب إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بعقوبــة تعزيريــة‬\n                                   ‫(علم ـ ًا بــأن احلــق اخلــاص انتهــى بالتنــازل) ‪.‬‬\n‫هــذه دعــواي علــى املدعــى عليهمــا وقــد أجــاب املدعــى عليــه ‪ ....‬قائــا‬\n‫إن مــا ذكــره املدعــي العــام يف الدعــوى غيــر صحيــح إال فيمــا ذكــر يف‬\n‫مبلــغ الســتني ألــف والصحيــح أننــي أعمــل مراســا ومعقبــا يف شــركة‬\n‫‪.....‬لوكالــة التأمــن وصاحبهــا ‪.....‬وقــد أخــذت مــن أموالهــا املبالــغ‬\n‫املذكــورة وقمــت بإخفائهــا يف اســتراحتي كمــا ذكــر واختلقــت‬\n‫قصــة الســرقة املذكــورة وليــس للمدعــى عليــه ‪.....‬أي عالقــة يف أخــذ‬\n‫أمــوال الشــركة بــل أحتملهــا لوحــدي وقــد أقرضنــي ســتني ألــف ريــال‬\n‫وســلمته إياهــا وقلــت يف التحقيــق إنهــا مــن أمــوال الشــركة واحلقيقــة‬\n‫أنهــا مــن أموالــي هكــذا أجــاب وأجــاب املدعــى عليــه ‪.....‬إننــي أعمــل‬\n‫يف شــركة ‪.....‬لوكالــة التأمــن مراســا وليــس لــي عالقــة باختــاس‬\n‫األمــوال وقــد أبلغنــي املدعــى عليــه ‪.....‬بتعرضــه للســطو مــن قبــل شــخص‬\n\n\n                                                                                          ‫‪14‬‬\n\f     ‫أخــذ مــال الشــركة منــه وقــد رأيــت زجــاج ســيارته مكســورا وبــه‬\n     ‫إصابــات فاتصلــت وأخبــرت الشــرطة وقــد ســلمني ســتني ألــف ريــال‬\n     ‫قرضــة حســنة ســلمتها لــه وقمــت بإرجاعهــا للشــركة ألنهــا وديعــة لــدي‬\n     ‫والشــركة تســتخدم حســابي يف اإليــداع والتحويــل ولــم أقــم بســرقة‬\n     ‫شــيء مــن أموالهــا هكــذا أجــاب وباالطــاع علــى أوراق املعاملــة ألفيــت‬\n     ‫أقــوال املدعــى عليــه ‪.....‬علــى ص‪ 4‬مــن آخــر ملــف يف التحقيــق يف الطــرد‬\n     ‫املرفــق باملعاملــة واملتضمــن إقــراره بســحب ســتني ألــف ريــال مــن حســاب‬\n     ‫الشــركة قبــل وقــوع احلادثــة بأســبوعني وقــد طلبــت الشــركة تســليم‬\n     ‫املبلــغ يف نفــس يــوم احلادثــة وعلــى ص‪ 5‬أنــه أعطــى هــذا املبلــغ للمدعــى‬\n     ‫عليــه ‪.....‬وأن ‪.....‬أرجــع لــه هــذا املبلــغ وأنــه قــام بإرجاعــه للشــركة‬\n     ‫إ‪.‬ه ـ وذلــك مرصــود يف إقــراره املصــدق شــرعا علــى ص‪ 3-2‬مــن امللــف‬\n     ‫الثانــي للتحقيــق وبعرضــه عليــه قــال وقعــت عليــه دون أن أقرأهــا وهــي‬\n     ‫صحيحــة ثــم جــرى ســؤال املدعــى عليــه كــم عــدد املبالــغ التــي أخذتهــا‬\n     ‫مــن الشــركة فقــال ســتون ألــف ريــال فقــط ثــم جــرى ســؤاله هــل‬\n     ‫يوجــد إثبــات ذلــك أن الشــركة تــودع يف حســابك فقــال نعــم كشــف‬\n     ‫حســاب وقــدم صــورة كشــف حســاب باســمه يف البنــك ‪...................‬‬\n     ‫ولــم يوجــد فيــه ذكــر للشــركة وإمنــا حتويــل مــن احلســاب للشــركة‬\n     ‫‪.....‬للتأمــن فقــال إن األمــوال تــودع بأســماء مندوبــي الشــركة فجــرى‬\n     ‫ســؤال املدعــى عليهمــا أيــن تودعــون أمــوال الشــركة فقــاال يف حســابها‬\n     ‫وهــو نفــس حســاب الشــركة ‪.....‬للتأمــن ألن الشــركة التــي نعمــل فيهــا‬\n     ‫مــن فروعهــا هكــذا أجابــا فبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة‬\n     ‫وإلقــرار املدعــى عليــه ‪.....‬مبــا جــاء يف الدعــوى وإقــرار املدعــى عليــه‬\n     ‫‪.....‬بأخــذه مبلــغ ســتني ألــف ريــال مــن أمــوال الشــركة وأنــه هــو املبلــغ‬\n\n\n‫‪15‬‬\n\f‫الوحيــد الــذي ســحبه منهــا لوجــود حســاب خــاص بالشــركة وإلقــرار‬\n‫املدعــى عليــه ‪.....‬بإرجاعــه املبلــغ يف يــوم احلادثــة ولظهــور اخليانــة بتصــرف‬\n‫املدعــى عليهمــا املذكــور ومشــروعية التعزيــر عليــه ملخالفتــه قــول اهلل‬\n‫تعالــى (إن اهلل يأمركــم أن تــؤدوا األمانــات إلــى أهلهــا) فقــد ثبــت لــدي‬\n‫إدانــة املدعــى عليهمــا بخيانــة األمانــة وأخــذ مبلــغ مالــي مــن الشــركة‬\n‫وحكمــت عليهمــا مبــا يلــي ‪ /1 :‬ســجن املدعــى عليــه ‪.....‬ثالثــون شــهرا‬\n‫وجلــده ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات كل دفعــة خمســون‬\n‫جلــدة ‪ /2‬ســجن املدعــى عليــه ‪.....‬ســنة وجلــده مائــة وعشــرين جلــدة‬\n‫مفرقــة علــى دفعتــن كل دفعــة ســتون جلــدة والســجن احملكــوم بــه‬\n‫يبــدأ مــن تاريــخ اإليقــاف واجللــد أمــام النــاس وبــن كل دفعتــن عشــرة‬\n‫أيــام وبعرضــه عليهمــا قــرر املدعــى عليهمــا القناعــة وقــرر املدعــي‬\n‫العــام االعتــراض مكتفيــا بالئحــة الدعــوى جــرى النطــق باحلكــم يف‬\n‫‪1434/03/14‬ه ـ وأغلقــت اجللســة الســاعة العاشــرة والنصــف وعليــه‬\n‫جــرى التوقيــع وصلــى اهلل علــى نبينــا محمــد ‪ .‬حــرر يف ‪1434/3/14‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم‬\n‫‪ 34275988‬وتاريــخ ‪1434/6/24‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬واملســجل برقــم ‪34227186‬‬\n‫وتاريــخ ‪1434/5/29‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد كل مــن‪/‬‬\n‫‪( .......... -2 ...... -1‬مينــي اجلنســية) التهامهمــا بخيانــة األمانــة وأخــذ مبلــغ‬\n‫مالــي علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل بــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n\n\n                                                                                          ‫‪16‬‬\n\f     ‫قررنــا باألكثريــة املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                            ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪17‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":10,"source_page_end":17,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d0011d660d22b687b7c25836f534e83cc0ac2efc4edec27a7c8747f77500c937","normalized_text_hash":"1a939c67b38ebfb660aeeadcd1a38efc735dcedc527b9b79263006f3e3763447","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p10-34227186"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"e52a531b-bbbd-521d-b6c4-6ffef69a7f09","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -اختاس -اختاس محاسب من الصندوق -خيانة أمانة -إقرار بالدعوى -ثبوت إدانة -تعزير بالسجن واجللد -تغليظ","document_number":"34216087","case_number":"34214538","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بأبو عريش املكلف والقائم بعمل املكتب القضائي الثاني","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/19","year":"1434","subject":"سرقة -اختاس -اختاس محاسب من الصندوق -خيانة أمانة -إقرار بالدعوى -ثبوت إدانة -تعزير بالسجن واجللد -تغليظ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34216087 :‬تاريخه‪1434/05/19 :‬هـ‬\n                           ‫رقم الدعوى‪34214538:‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34238495‬تاريخه‪1434/6/12 :‬هـ‬\n\n\n\n       ‫ســرقة ‪ -‬اختــاس ‪ -‬اختــاس محاســب مــن الصنــدوق ‪ -‬خيانــة أمانــة‬\n       ‫‪ -‬إقــرار بالدعــوى ‪ -‬ثبــوت إدانــة ‪ -‬تعزيــر بالســجن واجللــد ‪ -‬تغليــظ‬\n                                                                      ‫العقوبــة‪.‬‬\n\n\n\n\n                     ‫‪1 .1‬قول اهلل تعالى «وال تعتدوا إن اهلل ال يحب املعتدين»‬\n       ‫‪2 .2‬قــول النبــي صلــى اهلل عليــه وســلم «آيــة املنافــق ثــاث وذكــر منهــا‬\n                                                               ‫وإذا ائتمــن خــان»‬\n       ‫‪3 .3‬قــول النبــي صلــى اهلل عليــه وســلم «إن دمائكــم وأموالكم وأعراضكم‬\n                                                                    ‫حــرام عليكم»‬\n\n\n\n       ‫اتهــام املدعــي العــام للمدعــى عليــه باختــاس مبلــغ مالــي مــن خزنــة‬\n       ‫مجمــع ‪ ........‬حيــث كان يعمــل مســؤوال عــن الصنــدوق وطلــب إثبــات‬\n       ‫مــا أســند إليــه واحلكــم بتعزيــره شــرعا‪ ،‬حيــث إنــه طلــب مــن املدعــى‬\n       ‫عليــه جــردا علــى خزانــة املؤسســة للمجمــع كامــا حيــث أنــه كان‬\n       ‫املســؤول عنهــا ومت جــرد اخلزانــة واتضــح وجــود عجــز يف اخلزانــة قــدره‬\n       ‫ألفــا ومائتــان وخمســة وخمســون‬ ‫‪ 333.255‬ثالثمائــة وثالثــة وثالثــون ً‬\n       ‫ريــاال للمدعــو ‪ ....‬وباســتجواب املدعــى عليــه بعــد إحاطتــه بالتهمــة‬\n\n‫‪349‬‬\n\f‫املنســوبة إليــه أفــاد أنــه لــم يختلــس املبلــغ بالكامــل وإمنــا اختلــس مبل ًغــا‬\n‫ماليــا وقــدره ‪ 40.000‬أربعــون ألــف ريــاال حيــث كان يعمــل يف مؤسســة‬\n‫‪ ...‬مســؤوال عــن اخلزانــة وأنــه لــم يكــن الوحيــد الــذي يســجل فواتيــر‪،‬‬\n‫بــل كل العاملــن تســببوا يف العجــز ‪ ،‬وأمــا ســبب قيامــه باختــاس‬\n‫املبلــغ املذكــور فذكــر أن لديــه جمعيــة ويريــد الــزواج ومــن َثــم يعيدهــا‬\n‫‪ ،‬وأنــه مســتعد بتســديد املبلــغ للمؤسســة عــن طريــق األقســاط وصــادق‬\n‫حتقيقــا وقــد أســفر التحقيــق عــن توجيــه االتهــام للمدعــى‬ ‫ً‬         ‫علــى أقوالــه‬\n‫عليــه باختــاس مبلــغ مالــي وقــدره ‪ 333.255‬ثالثمائــة وثالثــة وثالثــون‬\n‫ألفــا ومائتــان وخمســة وخمســون ريــاال مــن خزنــة مجمــع ‪ ....‬حيــث كان‬          ‫ً‬\n‫يعمــل مســؤوال عــن الصنــدوق لديهــم بالبحــث عــن ســوابقه لــم يعثــر لــه‬\n                                           ‫علــى ســوابق مســجلة حتــى تاريخــه ‪.‬‬\n                                      ‫‪ -‬أقر املدعى عليه مبا جاء يف الدعوى ‪.‬‬\n                                   ‫‪ -‬ثبت إدانة املدعى عليه واحلكم مبا يلي ‪:‬‬\n    ‫‪ -1‬بالسجن ملدة عشرة أشهر من تاريخ إيقافه على ذمة هذه القضية‪.‬‬\n‫‪ -2‬باجللــد خمســمائة جلــده مفرقــة علــى عشــر دفعــات بــن كل دفعــة‬\n‫وأخــرى مــدة ال تقــل عــن عشــرة‪ ،‬قــرر املدعــي العــام عــدم القناعــة وطلــب‬\n‫االســتئناف بــدون الئحــة وقــرر املدعــى عليــه القناعــة‪ ،‬تصديــق احلكــم‬\n                                                       ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد فلــدي‬\n‫أنــا ‪ ....‬رئيــس احملكمــة العامــة بأبــو عريــش املكلــف والقائــم بعمــل‬\n‫املكتــب القضائــي الثانــي وبنــاء علــى املعاملــة الــواردة إلينــا مــن دائــرة‬\n\n                                                                                           ‫‪350‬‬\n\f      ‫التحقيــق واالدعــاء العــام بأبــو عريــش برقــم ه ـ ج‪ 1058/2/3‬وتاريــخ‬\n      ‫‪1434/5/5‬ه ـ واحملالــة إلينا بشــرح رئيــس احملكمة برقم ‪34214538‬‬\n      ‫وتاريــخ ‪1434/5/8‬ه ـ واملقيــدة باحملكمــة برقــم ‪ 341125901‬وتاريــخ‬\n      ‫‪1434/5/7‬ه ـ ففــي يــوم األحــد املوافــق ‪1434/5/19‬ه ـ افتتحــت‬\n      ‫اجللســة األولــى يف متــام الســاعة العاشــرة وفيهــا حضــر املدعــي العــام‬\n      ‫بدائــرة التحقيــق واالدعــاء العــام مبحافظــة أبــو عريــش ‪ .....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....‬واملفــوض باخلطــاب رقــم ه ـ‬\n      ‫ج ‪ 513/630/‬وتاريــخ ‪1429/11/3‬ه ـ وأدعــى قائــا بصفتــي مدعيــا‬\n      ‫عامــا بدائــرة االدعــاء العــام مبحافظــة أبــو عريــش أدعــي علــى ‪29 ....‬‬\n      ‫عامــا ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬مــودع بقســم‬       ‫ً‬\n      ‫ســجن أبــي عريــش مبوجــب أمــر متديــد التوقيــف واإلحالــة رقــم ‪3348‬‬\n      ‫وتاريــخ ‪1434/2/19‬ه ـ لكــون جرميتــه مــن اجلرائــم املوجبــة للتوقيــف‬\n      ‫ويعــد إيقافــه مــن تاريــخ‬  ‫اســتنا ًدا للقــرار الــوزاري رقــم ‪ 1900‬وتاريــخ ُ‬\n      ‫القبــض عليــه بتاريــخ إنــه يف متــام الســاعة التاســعة والنصــف مــن صبــاح‬\n      ‫يــوم االثنــن ‪1434/2/4‬ه ـ حضــر لشــرطة صبيــا ‪ ....‬مفيــدا أنــه يف بدايــة‬\n      ‫شــهر رمضــان مــن العــام املاضــي طلــب مــن املدعــى عليــه جــردا علــى‬\n      ‫خزانــة املؤسســة للمجمــع كامــا حيــث أنــه كان املســؤول عنهــا وبعــد‬\n      ‫ذلــك لــم يعــد يــداوم أبــدا ومت االتصــال عليــه وإبالغــه بأنــه ســوف يقــوم‬\n      ‫بإبــاغ الشــرطة يف عــدم حضــوره وحضــر معــه إخوانــه ومت جــرد اخلزانــة‬\n      ‫واتضــح وجــود عجـ ٍـز يف اخلزانــة قــدره ‪ 333255‬ثالثمائــة وثالثــة وثالثــون‬\n      ‫ألفــا ومائتــان وخمســة وخمســون ريــاال للمدعــو ‪ ....‬وباســتجواب املدعــى‬       ‫ً‬\n      ‫عليــه بعــد إحاطتــه بالتهمــة املنســوبة إليــه أفــاد أنــه لــم يختلــس املبلــغ‬\n      ‫بالكامــل وإمنــا اختلــس مبل ًغــا ماليــا وقــدره ‪ 40000‬أربعــون ألفــا ريــاال‬\n\n\n‫‪351‬‬\n\f‫وكان ذلــك يف عــام ‪ 2011‬شــهر ‪ 7‬أو ‪ 8‬ال يعلــم حتديــدا حيــث كان‬\n‫يعمــل يف مؤسســة ‪ ...‬مســؤوال عــن اخلزانــة وأنــه لــم يكــن الوحيــد الــذي‬\n‫يســجل فواتيــر بــل كل العاملــن تســببوا يف العجــز وأمــا ســبب قيامــه‬\n‫باختــاس املبلــغ املذكــور فذكــر أن لديــه جمعيــة ويريــد الــزواج ومــن‬\n‫َثــم يعيدهــا وأنــه مســتعد بتســديد املبلــغ للمؤسســة عــن طريــق األقســاط‬\n‫حتقيقــا وقــد أســفر التحقيــق عــن توجيــه االتهــام‬\n                                                   ‫ً‬     ‫وصــادق علــى أقوالــه‬\n‫للمدعــى عليــه باختــاس مبلــغ مالــي وقــدره ‪ 333255‬ثالثمائــة وثالثــة‬\n‫ألفــا ومائتــان وخمســة وخمســون ريــاال مــن خزنــة مجمــع ‪...‬‬    ‫وثالثــون ً‬\n‫حيــث كان يعمــل مســؤوال عــن الصنــدوق لديهــم وذلــك لألدلــة والقرائن‬\n‫التاليــة مــا جــاء يف إقــرار حتقيق ـ ًا املــدون ص ‪ 1‬مــن دفتــر التحقيــق لفــة‬\n‫رقــم ‪ 1‬مــا جــاء يف أقوالــه املدونــة ص ‪ 14‬مــن دفتــر التحقيــق لفــة رقــم ‪2‬‬\n‫مــا جــاء يف تقريــر احملاســب القانونــي املرفــق لفــة ر قــم ‪ 3‬وبالبحــث عــن‬\n‫ســوابقه لــم يعثــر لــه علــى ســوابق مســجلة حتــى تاريخــه وحيــث أن مــا‬\n‫أقــدم عليــه املدعــى عليــه فعــل محــرم شــرعا ومعاقــب عليــه لــذا أطلــب‬\n‫إثبــات مــا أســند إليــه واحلكــم بتعزيــره شــرعا علمــا بــأن احلــق اخلــاص‬\n‫قائمــا وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه بعــد‬‫مــا زال ً‬\n‫التأكــد مــن هويتــه وأهليتــه املعتبــرة شــرعا أجــاب قائــا مــا ذكــره‬\n‫املدعــي العــام مــن قيامــي باختــاس مبلــغ مالــي وقــدره‪ 333255‬ريــاال‬\n‫مــن خزنــة مجمــع ‪ ...‬فصحيــح هكــذا أجــاب عقــب ذلــك جــرى االطــاع‬\n‫علــى كــرت ســوابق املدعــى عليــه لفــة رقــم‪ 19‬فوجدتهــا خاليــة مــن‬\n‫الســوابق عقــب ذلــك جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه‬\n‫لفــه رقــم‪ 9‬أنهمــا أوقفــا بتاريــخ ‪1434/2/16‬ه ـ فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة ومبــا أن املدعــي العــام يتهــم املدعــى عليــه بقيامــه‬\n\n\n                                                                                      ‫‪352‬‬\n\f      ‫ألفــا‬\n          ‫باختــاس مبلــغ مالــي وقــدره ‪ 333255‬ثالثمائــة وثالثــة وثالثــون ً‬\n      ‫ومائتــان وخمســة وخمســون ريــاال مــن خزنــة مجمــع ‪ ...‬ومبــا أن املدعــى‬\n      ‫عليــه صــادق علــى دعــوى املدعــي العــام ومبــا أن مــا قــام بــه املدعــى عليــه‬\n      ‫فعــل محــرم شــرعا ولقولــه تعالــى» وال تعتــدوا إن اهلل ال يحــب املعتديــن»‬\n      ‫ولقــول النبــي صلــى اهلل عليــه وســلم أيــة املنافــق ثــاث وذكــر منهــا وإذا‬\n      ‫ائتمــن خــان ونظــرا لكــون املدعــى عليــه اختلــس ممــن ائتمنــه ولقــول‬\n      ‫النبــي صلــى اهلل عليــه وســلم «إن دمائكــم وأموالكــم وأعراضكــم‬\n      ‫حــرام عليكــم» كمــا يتوجــب مــع ذلــك تغليــظ العقوبــة ولذلــك كلــه‬\n      ‫وألجــل احلــق العــام فقــد قــررت مــا يلــي أوال ثبــت لــدي إدانــة املدعــى عليــه‬\n      ‫بقيامــه باختــاس مبلــغ مالــي وقــدره ‪ 333.255‬ثالثمائــة وثالثــة وثالثون‬\n      ‫ألفــا ومائتــان وخمســة وخمســون ريــاال مــن خزنــة مجمــع ‪ ...‬ثانيــا يعــزر‬     ‫ً‬\n      ‫املدعــى عليــه بالســجن ملــدة عشــرة أشــهر مــن تاريــخ إيقافــه علــى ذمــة‬\n      ‫هــذه القضيــة ثالثــا يعــزر املدعــى عليــه باجللــد خمســمائة جلــده مفرقــة‬\n      ‫علــى عشــر دفعــات بــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيــام‬\n      ‫وبجميــع مــا تقــدم حكمــت وبعــرض احلكــم علــى املدعــي العــام قــرر‬\n      ‫عــدم القناعــة بــدون الئحــة اعتراضيــة وبعــرض احلكــم علــى املدعــى‬\n      ‫عليــه قــرر القناعــة عليــه أمــرت برفــع كامــل أوراق املعاملــة حملكمــة‬\n      ‫االســتئناف لتدقيــق احلكــم وحتــى ال يخفــى جــرى تدوينــه وبــاهلل‬\n      ‫التوفيــق وأقفلــت اجللســة يف متــام الســاعة احلاديــة عشــر وصلــى اهلل وســلم‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/5/19‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بأبــي عريــش املكلــف‬\n\n\n‫‪353‬‬\n\f‫الشــيخ ‪ .... /‬برقــم ‪ 341125901‬وتاريــخ ‪1434/5/21‬ه ـ املرفــق بهــا‬\n‫القرار الصادر من فضيلته برقم ‪ 34216087‬وتاريخ ‪1434/5/19‬هـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد ‪ ( ....‬ســعودي اجلنســية ) يف قضيــة‬\n‫(اختــاس مبلــغ مالــي) علــى الصفــة املوضحــة يف القــرار املتضمن حكم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                                  ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪354‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":349,"source_page_end":354,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"050dc683a5da6ccf10c8513827fa83e8a896d8d0c621f3f6e617b4f12546c6f1","normalized_text_hash":"58ee7f079a099f88461fdb07edf95117581b7438f245d9ade2472f7bb33457ff","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p349-34216087"},{"id":"211102cc-bf36-5cc3-8f74-fa5a70984151","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة حافظة نقود من داخل سيارة -تشديد العقوبة لوجود عدة سوابق قضائية -إقرار املدعى عليه -تعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","document_number":"34344724","case_number":"34478707","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/29","year":"1434","subject":"سرقة -سرقة حافظة نقود من داخل سيارة -تشديد العقوبة لوجود عدة سوابق قضائية -إقرار املدعى عليه -تعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34344724 :‬تاريخه‪1434/10/29 :‬هـ‬\n                           ‫رقم الدعوى‪34478707 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34354347‬تاريخه‪1434/11/9 :‬هـ‬\n\n\n\n       ‫ســرقة ‪ -‬ســرقة حافظــة نقــود مــن داخــل ســيارة ‪ -‬تشــديد العقوبــة‬\n       ‫لوجــود عــدة ســوابق قضائيــة ‪ -‬إقــرار املدعــى عليــه ‪ -‬تعزيــر بالســجن‬\n                                     ‫واجللــد والتوصيــة باإلبعــاد عــن البــاد‪.‬‬\n\n\n\n\n                                      ‫القاعدة الشرعية ( املرء مؤاخذ بإقراره ) ‪.‬‬\n\n\n\n\n       ‫اتهــام املدعــي العــام للمدعــى عليــه بســرقة حافظــة نقــود مــن ســيارة‬\n       ‫وطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــه‬\n       ‫وتشــديد العقوبــة عليــه لكثــرة ســوابقه التــي لــم تردعــه عقوباتهــا‪،‬‬\n       ‫حيــث إنــه تبلــغ ملركــز الشــرطة مــن قبــل املجنــي عليــه تعرضــه للســرقة‬\n       ‫مــن داخــل ســيارته وســرقة بطاقــات رســمية‪ ،‬وبتاريــخ الحــق تبــن أنــه‬\n       ‫مت القبــض علــى املدعــى عليــه املذكــور وبتفتيشــه عثــر علــى إثبــات‬\n       ‫شــخصي ورخصــة ســير لســيارة تعــود للمبلــغ‪ ،‬أقــر املدعــى عليــه مبــا‬\n       ‫جــاء يف الدعــوى ‪ ،‬فبنــاء علــى مــا تقــدم ويالحــظ كثــرة ســوابق املدعــى‬\n       ‫عليــه ‪ ،‬ثبــت إدانــة املدعــى عليــه وصــدر احلكــم بالســجن ســنتني ابتــداء‬\n       ‫مــن تاريــخ إيقافــه يف هــذه القضيــة‪ ،‬وجلــده ثمامنائــة جلــدة مفرقــة علــى‬\n       ‫ســتة عشــر دفعــة متســاوية كل دفعــة خمســون جلــدة بــن كل دفعــة‬\n\n‫‪355‬‬\n\f‫واألخــرى مــدة ال تقــل عــن عشــرة أيــام وأن يكــون اجللــد يف مــكان‬\n‫عــام‪ ،‬والتوصيــة بإبعــاده عــن البــاد بعــد انتهــاء محكوميتــه‪ ،‬وقــرر‬\n‫املدعــى العــام االعتــراض وطلــب االســتئناف بــدون الئحــة وقــرر املدعــى‬\n           ‫عليــه القناعــة‪ ،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بحائــل برقــم ‪ 34478707‬وتاريــخ ‪1434/10/27‬ه ـ املقيــدة‬         ‫ّ‬\n‫باحملكمــة برقــم ‪ 342439592‬وتاريــخ ‪1434/10/27‬ه ـ ففــي يــوم‬\n‫اخلميــس املوافق‪1434/10/29‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 00‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ .....‬بصفتــه مدعي ـ ًا عام ـ ًا يف دائــرة االدعــاء‬\n‫العــام بفــرع هيئــة التحقيــق و االدعــاء العــام مبنطقــة حائــل وأدعــى‬\n‫علــى احلاضــر معــه ‪ ....-1‬فلســطيني اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫رقــم (‪ )....‬قائــا يف دعــواه ‪ .‬تاريــخ ‪1434/8/16‬ه ـ تبلــغ مركــز شــرطة‬\n‫بريــدة الشــمالي مــن قبــل املواطــن‪ .... /‬تعرضــه لســرقة اســتمارة ســيارته‬\n‫وبطاقــة األحــوال املدنيــة اخلاصــة بــه وبطاقــة هيئــة التخصصــات الطبيــة‬\n‫وبطاقــة اإلنعــاش القلبــي مــن داخــل ســيارته‪ .‬وبتاريــخ ‪1434/8/17‬ه ـ‬\n‫ورد ملركــز شــرطة بريــدة الشــمالي خطــاب مديــر شــرطة منطقــة حائــل‬\n‫رقــم (‪ )5699‬وتاريــخ ‪1434/8/17‬ه ـ املتضمــن أنــه مت القبــض علــى‬\n‫املدعــى عليــه املذكــور وبتفتيشــه عثــر علــى إثبــات شــخصي ورخصــة‬\n‫ســير لســيارة مــن نــوع ‪ ...‬تعــود للمبلــغ‪ .‬وباســتجواب املدعــى عليــه أقــر‬\n‫بقيامــه بســرقة محفظــة مــن ســيارة نــوع ‪ ....‬كانــت متوقفــة يف مواقــف‬\n\n                                                                                       ‫‪356‬‬\n\f      ‫املستشــفى ‪ ،‬وأضــاف أنــه وجــد الســيارة غيــر مقفلــة ووجــد بداخلهــا‬\n      ‫احملفظــة فقــام بفتــح الســيارة وأخــذ احملفظــة مــن داخلهــا‪ .‬وقــد أســفر‬\n      ‫التحقيــق معــه عــن اتهامــه بســرقة محفظــة مــن ســيارة بداخلهــا بطاقــة‬\n      ‫األحــوال املدنيــة واســتمارة ســيارة وبطاقــة هيئــة التخصصــات الطبيــة‬\n      ‫وبطاقــة اإلنعــاش القلبــي عائــدة للمبلــغ‪ .... /‬وذلــك لألدلــة والقرائــن‬\n      ‫التاليــة ‪ - 1 :‬مــا جــاء باعترافــه املنــوه عنــه املــدون علــى الصفحــة رقــم‬\n      ‫(‪ 9‬ـ ـ ‪ )10‬مــن ملــف محاضــر إجــراءات االســتدالل األوليــة املرفــق لفــة‬\n      ‫(‪ ، 2.)1‬مــا جــاء بخطــاب مديــر شــرطة منطقــة حائــل رقــم (‪)5699‬‬\n      ‫وتاريــخ ‪1434/8/17‬ه ـ املرفــق صورتــه لفــة (‪ )6‬املتضمــن القبــض علــى‬\n      ‫املدعــى عليــه وبحوزتــه إثبــات شــخصي ورخصــة ســير لســيارة تعــود‬\n      ‫للمواطــن ‪.....‬وبالبحــث يف ســجله اجلنائــي اتضــح وجــود ســتة ســوابق‬\n      ‫األولــى هــروب وتغيــب والثانيــة ســرقة ســيارات ومنــازل والثالثــة دخــول‬\n      ‫منــزل لغــرض ســيء وســرقته والرابعــة حيــازة مخــدرات واخلامســة ســرقة‬\n      ‫ذهــب ومجوهــرات والسادســة ســرقة كيابــل‪ .‬وحيــث إن مــا أقــدم عليــه‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات إدانتــه مبــا أســند إليــه‬\n      ‫واحلكــم عليــه بعقوبــة تعزيريــه تزجــره وتــردع غيــره وتشــديد العقوبــة‬\n      ‫عليه لكثرة ســوابقه التي لم تردعه عقوباتها‪ .‬وبالل ــه التوفي ــق وبعرض‬\n      ‫دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي‬\n      ‫العــام يف دعــواه صحيــح وأنــا نــادم علــى فعلــي وتائــب إلــى اهلل تعالــى‬\n      ‫هكــذا أجــاب وبســؤال املدعــى عليــه عــن الســوابق املذكــورة أعــاه‬\n      ‫يف دعــوى املدعــي العــام أجــاب كلهــا صحيحــة ســوى ســرقة الكيابــل‬\n      ‫ودخــول منــزل والهــروب هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة وإقــرار املدعــى عليــه مبــا جــاء يف دعــوى املدعــي العــام وألنــه‬\n\n\n‫‪357‬‬\n\f‫ال عــذر ملــن أقــر ولكــون مــا فعلــه املدعــى عليــه يعتبــر تعديــا علــى حــق‬\n‫الغيــر بغيــر وجــه حــق وملــا تقــدم كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه‬\n‫مبــا نســب إليــه يف دعــوى املدعــي العــام ونظــر ًا لكثــرة ســوابقه وعــدم‬\n‫ارتداعــه فقــد حكمــت عليــه بأن يســجن ســنتني ابتداء مــن تاريخ إيقافه‬\n‫يف هــذه القضيــة وجلــده ثمامنائــة جلــدة مفرقــة علــى ســتة عشــر دفعــة‬\n‫متســاوية كل دفعــة خمســون جلــدة بــن كل دفعــة واألخــرى مــدة ال‬\n‫تقــل عــن عشــرة أيــام وأن يكــون اجللــد يف مــكان عــام وأوصيــت بإبعــاده‬\n‫عــن البــاد بعــد انتهــاء محكوميتــه وبعــرض احلكــم علــى املدعــي العــام‬\n‫واملدعــى عليــه قــرر املدعــي العــام عــدم القناعــة باحلكــم وطلــب رفــع‬\n‫املعاملــة حملكمــة االســتئناف بــدون الئحــة وقــرر املدعــى عليــه القناعــة‬\n‫باحلكــم وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n             ‫وصحبــه أجمعــن حــرر يف ‪1434/10/29‬ه ـ الســاعة ‪09.30‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولــى‬\n‫املختصــة بتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة‬\n‫حائــل علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بحائل‬\n‫برقــم‪ 342439592‬يف تاريــخ ‪1434 /11/5‬ه ـ واملقيــدة لدينــا برقــم‬\n‫‪ 342439592‬يف تاريــخ ‪1434 /11/6‬ه ـ املرفــق بهــا القــرار الشــرعي‬\n‫الصــادر مــن صاحــب الفضيلــة الشــيخ ‪ .... /‬القاضــي باحملكمة اجلزائية‬\n‫بحائــل برقــم ‪ 34344724‬يف تاريــخ ‪1434/10/29‬ه ـ اخلــاص بدعــوى‬\n‫املدعــي العــام ضــد‪( .....‬فلســطيني اجلنســية) مبوجــب اإلقامــة رقــم(‪)....‬‬\n‫بشــأن ســرقة وقــد تضمــن القــرار حكــم صاحــب الفضيلــة وفقــه اهلل‬\n‫علــى املدعــى عليــه علــى النحــو املفصــل يف القــرار املرفــق‪ ،‬وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة‪ .‬جــرت املصادقــة علــى ماحكــم‬\n\n\n                                                                                          ‫‪358‬‬\n\f      ‫بــه فضيلتــه بالقــرار املشــار إليــه‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى‬\n                                       ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪359‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":355,"source_page_end":359,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"776eadbb008a10f2fff823c37866d22c05a24ecadcaa7c0b27df58f2d5db1d93","normalized_text_hash":"b576cc94693ab81a89fe66200c44cc1b47c437b250a76b91d57873fd8d47ff61","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p355-34344724"},{"id":"0be81d8e-045f-5b1d-824f-7851d344c510","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة مبلغ مالي وجهاز جوال من داخل منزل -انتهاك حرمة منزل -تعظيم اجلناية يف بلد اهلل احلرام -ثبوت اإلدانة بالسرقة -تنازل عن احلق اخلاص -تعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","document_number":"34352474","case_number":"34489903","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/06","year":"1434","subject":"سرقة -سرقة مبلغ مالي وجهاز جوال من داخل منزل -انتهاك حرمة منزل -تعظيم اجلناية يف بلد اهلل احلرام -ثبوت اإلدانة بالسرقة -تنازل عن احلق اخلاص -تعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34352474 :‬تاريخه‪1434/11/06 :‬هـ‬\n                     ‫رقم الدعوى‪34489903 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34375433‬تاريخه‪1434/12/2 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة مبلــغ مالــي وجهــاز جــوال مــن داخــل منــزل ‪ -‬انتهــاك‬\n‫حرمــة منــزل ‪ -‬تعظيــم اجلنايــة يف بلــد اهلل احلــرام‪ -‬ثبــوت اإلدانــة‬\n‫بالســرقة ‪ -‬تنــازل عــن احلــق اخلــاص ‪ -‬تعزيــر بالســجن واجللــد‬\n                                         ‫والتوصيــة باإلبعــاد عــن البــاد‪.‬‬\n\n\n\n\n              ‫‪1 .1‬التعزير يشرع يف كل معصية ال حد فيها وال كفارة‪.‬‬\n‫‪2 .2‬تقديــر التعزيــر راجــع لنظــر احلاكــم مبــا يــراه محقق ـ ًا للزجــر‬\n                                                               ‫والــردع‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى ضــد املدعــى عليــه بدخــول منــزل ‪ ،‬وســرقة مبلــغ مالــي‬\n‫وجهــازي جــوال مــن املجنــي عليــه أثنــاء نومــه ‪ ،‬وطلــب املدعــي العــام‬\n‫إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة ‪ ،‬مت القبــض علــى‬\n‫املدعــى عليــه ووجــد أحــد اجلــوالت املســروقة بحوزتــه واعتــرف املدعــى‬\n‫عليــه بالدعــوى ‪ ،‬حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن‬\n‫واجللــد والتوصيــة بإبعــاده عــن البــاد ‪ ،‬مت تصديــق احلكــم من محكمة‬\n                                                                  ‫االســتئناف‪.‬‬\n\n\n                                                                                   ‫‪360‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 34489903‬وتاريــخ‬\n      ‫‪ 1434/11/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 342491638‬وتاريــخ‬\n      ‫‪ 1434/11/03‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1434/11/05‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 11 : 15‬وفيهــا حضــر املدعــي العــام بهيئــة‬\n      ‫التحقيــق واالدعــاء العــام باملدينــة املنــورة ‪..........‬و أدعــى علــى احلاضــر‬\n      ‫معــه مبجلــس احلكــم ‪..........‬باكســتاني اجلنســية مبوجــب رخصــة‬\n      ‫اإلقامــة الصــادرة مــن جــوازات املدينــة املنــورة بالرقــم ‪..........‬قائــا يف‬\n      ‫حتريــر دعــواه إنــه بتاريــخ ‪ 1434/8/16‬ه ـ أبلــغ ‪..........‬مينــي اجلنســية بأنــه‬\n      ‫بعــد إغــاق احملــل الــذي يعمــل بــه عنــد الســاعة الواحــدة ليــا اجتــه‬\n      ‫إلــي منزلــه الكائــن يف احلــي نفســه وكان بحوزتــه مبلغــا وقــدره ســبعة‬\n      ‫وعشــرون ألــف ريــال منهــا ســتة عشــر ألــف ريــال عائــدة لكفيلــه ‪..........‬و‬\n      ‫هــي إيــرادات املطعــم وثمانيــة اآلف عائــدة لــه شــخصيا والباقــي أمانــة‬\n      ‫لديــه وكان املبلــغ بداخــل جيــب بنطلونــه خــاص و وضعــه أســفل املخــدة‬\n      ‫التــي ينــام عليهــا وجــواره جهــازي جــوال خــاص بــه ثــم خلــد إلــى النــوم‬\n      ‫وعندمــا اســتيقظ عنــد الســاعة الثالثــة فجــرا وجــد البنطلــون الــذي بــه‬\n      ‫املبلــغ املســروق وأيضــا جهــازي اجلــوال غيــر موجديــن وال يتهــم أحــدا‬\n      ‫بالســرقة ومبعاينــة املنــزل رفــق األدلــة اجلنائيــة اتضــح أنــه يقــع يف حــي‬\n      ‫‪..........‬باملدينــة املنــورة وهــو عبــارة عــن منــزل شــعبي مكــون مــن دور‬\n      ‫واحــد ولــه بــاب بالناحيــة اجلنوبيــة ويطــل علــى شــارع صغيــر ولــه بــاب‬\n\n‫‪361‬‬\n\f‫حديــد ويوجــد ســلك حديــدي موصــل بقفــل البــاب وبــارز للخــارج يتــم‬\n‫مــن خاللــه فتــح البــاب حيــث إنــه ال يقومــون بإغــاق البــاب باملفتــاح وال‬\n‫يوجــد أي أثــار عنــف أو تكســير كمــا أنــه مبعاينــة املنــزل مــن الداخــل‬\n‫اتضــح أنــه املنــزل يحتــوي علــى غرفتــن ولــم يالحــظ أي أثــار بعثــرة أو‬\n‫عنــف أو تكســير علــى بــاب الغرفــة املتعرضــة للســرقة حيــث أفــاد املبلــغ‬\n‫أن املســروقات كانــت بداخــل بنطلــون خــاص بــه أســفل مخدتــه وســرق‬\n‫أثنــاء نومــه وبتاريــخ ‪ 1434/8/20‬ه ـ مت القبــض علــى املدعــى عليــه مــن‬\n‫قبــل قســم البحــث والتحــري باملركــز وضبــط أحــد اجلــواالت املســروقة‬\n‫بحوزتــه وباســتجواب املدعــى عليــه أفــاد أنــه عنــد الســاعة (‪ )2 : 30‬ليــا‬\n‫مــن يــوم ‪ 1434/8/16-15‬ه ـ ذهــب إلــى منــزل عمــال باملدينــة املنــورة‬\n‫وقــام بفتــح البــاب الرئيســي ملنزلهــم بواســطة حبــل مربــوط يف البــاب‬\n‫ودخــل لغرفــة العمــال ووجــد بداخلهــا أربعــة أشــخاص قــد نامــوا وقــام‬\n‫بســرقة جهــاز جــوال وبنطلــون أحــد العمــال وجــد بجــوار املخــدة عنــد نــوم‬\n‫أحــد األشــخاص عليــه ووجــد بداخلــه مبلــغ ســتة وعشــرين ألــف ريــال‬\n‫وقــام بصــرف املبلــغ علــى نفســه ولــم يتبقــى منــه ســوي مبلــغ ثمانيــة اآلف‬\n‫ومائــة ريــال وقــام بتســليمها للشــرطة وأضــاف أنــه قــام بالســرقة لوحــده‬\n‫ولــم يكــن معــه أحــد وباالنتقــال رفــق املدعــى عليــه لإلرشــاد علــى املنــزل‬\n‫الــذي اعتــرف بســرقته وذلــك للتأكــد مــن صحــة اعترافــه وقــد ارشــد‬\n‫املذكــور علــى منــزل املدعــو ‪..........‬مينــي اجلنســية بحــي ‪..........‬وأضــاف‬\n‫أن هــذا املنــزل هــو الــذي قــام بالدخــول إليــه وســرقة مبلــغ وقــدره ســتة‬\n‫وعشــرون ألــف ريــال كانــت يف بنطلــون أســفل مخــدة كان ينــام عليهــا‬\n‫املدعــى وقــد انتهــي التحقيــق إلــى توجيــه االتهــام إلــى املدعــى عليــه‬\n‫بدخــول منــزل وســرقة ســبعة وعشــرين ألــف ريــال مــن داخــل بنطلــون‬\n\n\n                                                                                      ‫‪362‬‬\n\f      ‫خــاص باملدعــي كان أســفل املخــدة التــي ينــام عليهــا وجهــازي جــوال‬\n      ‫أثنــاء نومــه وذلــك لألدلــة والقرائــن التاليــة مــا جــاء باعترافــه املــدون علــى‬\n      ‫ص ‪ 4‬مــن ملــف التحقيــق لفــة ‪ 2‬مــا جــاء مبحضــر القبــض لفــة (‪)16‬‬\n      ‫إرشــاده وإحضــاره جلــزء مــن املبلــغ املســروق مــا جــاء مبحضــر االســتدالل‬\n      ‫والتثبــت وإرشــاده للمنــزل املســروق املــدون علــى ص ‪ 4‬مــن ملــف التحقيق‬\n      ‫لفــة ‪ 1‬تعــرف املدعــي علــى جهــاز جوالــه حســب محضــر العــرض‬\n      ‫املــدون يف األوراق علــى ص ‪ 11‬مــن ملــف التحقيــق لفــة ‪ 1‬وبالبحــث‬\n      ‫عــن ســوابقه لــم يعثــر لــه علــى ســوابق جنائيــة مســجلة وحيــث إن مــا‬\n      ‫أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرعا اطلــب إثبــات‬\n      ‫مــا اســند إليــه واحلكــم بتعزيــره لقــاء ذلــك علمــا أنــه تنــازل عــن احلــق‬\n      ‫اخلــاص وهــو ســجني علــى ذمــة هــذه الدعــوى منــذ تاريــخ ‪1434/8/16‬‬\n      ‫ه ـ هــذه دعــواي وبســؤال املدعــى عليــه عمــا جــاء بدعــوى املدعــي العــام‬\n      ‫أجــاب وهــو ينطــق بالعربيــة قائــا مــا ذكــره املدعــي العــام يف دعــواه‬\n      ‫صحيــح جملــة وتفصيــا ففــي التاريــخ املذكــور يف الدعــوى دخلــت إلــى‬\n      ‫املنــزل املبــن أنفــا عــن طريــق بابــه اخلارجــي وكان مفتوحــا وقــد جــدت‬\n      ‫أهلــه نامــوا فســرقت منــه جهــازي جــوال نــوع نوكيــا كانــت علــى طاولــة‬\n      ‫بالقــرب مــن ســرير نــوم أحــد أهــل املنــزل كمــا وجــدت بنطــاال بالقــرب‬\n      ‫مــن أحــد النائمــن وكان فيــه مبلــغ وقــدره ســبعة وعشــرون ألــف ريــال‬\n      ‫فســرقت ذلــك املبلــغ ولــم يشــعر بــي أحــد ممــن كان باملنــزل املذكــور‬\n      ‫لكــون جميــع أبــواب غرفــه مفتوحــة وقــد تصرفــت يف بعــض املبلــغ‬\n      ‫املســروق وســلمت جــزء منــه إلــى اجلهــات األمنيــة كمــا ســلمتهم جهــازي‬\n      ‫اجلــوال و أنــا نــادم علــى فعلــي هــذا وتائــب هلل تعالــى هكــذا أجــاب هــذا‬\n      ‫وبالرجــوع إلــى املعاملــة وجــد بهــا تنــازل أصحــاب احلــق اخلــاص و إقرارهم‬\n\n\n‫‪363‬‬\n\f‫باســتالم جميــع حقوقهــم املســروقة فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة ومبــا أن املدعــى عليــه صــادق علــى دعــوى املدعــي العــام فأقــر‬\n‫بدخــول املنــزل املذكــور يف الدعــوى وســرقة املســروقات املبينــة آنفــا‬\n‫منــه ومبــا أن مــا أقــدم عليــه املدعــى عليــه اعتــداء آثــم و إخافــة للنــاس‬\n‫علــى أموالهــم و أخذهــا بالباطــل ومبــا أن الســرقة املذكــورة يف الدعــوى‬\n‫لــم تكــن مــن حــرز ومبــا أن هــذه اجلنايــة وقعــت يف بلــد اهلل احلــرام الــذي‬\n‫رفــع اهلل مكانــه وتوعــد بالعقــاب علــى مــن انتهــك محارمــه ومبــا أن‬\n‫التعزيــر يشــرع يف كل معصيــة ال حــد فيهــا وال كفــارة وهــو يختلــف‬\n‫باختــاف األحــوال واألشــخاص والزمــان واملــكان وتقديــر ذلــك راجــع‬\n‫لنظــر احلاكــم مبــا يــراه محققــا للزجــر والــردع جلميــع مــا ذكــر فقــد‬\n‫حكمــت بثبــوت إدانــة املدعــى عليــه مبــا نســب إليــه يف الدعــوى وقــررت‬\n‫تعزيــره علــى ذلــك بجلــد ألــف ومائتــي جلــدة تقــع علــى بدنــه علــى أربعــة‬\n‫وعشــرين دفعــة متســاوية وبــن كل دفعــة و أخــرى عشــرة أيــام ويســجن‬\n‫ســنة كاملــة ابتــداء مــن تاريــخ إيقافــه و أرى إبعــاده إلــى بلــده بعــد انتهــاء‬\n‫محكوميتــه و بعــد إنهــاء جميــع املطالبــات التــي لــه أو عليــه إن وجــدت‬\n‫وبعرضــه قــرر املدعــى عليــه قناعتــه باحلكــم أمــا املدعــي العــام قــرر‬\n‫عــدم القناعــة باحلكــم وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة‬\n‫إعتراضيــة فأجيــب لطلبــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/11/05‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ :‬ـ ـ نحــن رئيــس‬\n‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقــة‬\n‫مكــة املكرمــة جــرى منــا االطــاع على القــرار رقــم ‪34352474‬وتاريخ‬\n‫‪1434/11/6‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪.......... .‬القاضي باحملكمة‬\n\n\n                                                                                          ‫‪364‬‬\n\f      ‫اجلزائيــة باملدينــة املنــورة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪.......... /‬‬\n      ‫باكســتاني اجلنســية ‪ ،‬املتهــم يف قضيــة ســرقة‪ ،‬احملكــوم فيــه مبــا دون‬\n      ‫باطنــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه تقــرر باألكثريــة املوافقــة‬\n      ‫علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                      ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪365‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":360,"source_page_end":365,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4961046c1b694a0a41fdea53f84925862515fd16efe5a6e8de033d27aa17caef","normalized_text_hash":"6b13c3c6c429cba0617029bddb70c5468719aa7067daaa960c6cfe53098d82de","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p360-34352474"},{"id":"704b391c-f00a-5c95-8ce7-c8b22be08163","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -تقرير فني البصمات -ثبوت إدانة املدعى عليه -وجود سوابق قضائية -تقرير بالسجن واجللد -أخذ تعهد بعدم تكرار الفعل .","document_number":"34378220","case_number":"34540463","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/12/4","year":"1434","subject":"سرقة -سرقة سيارة -تقرير فني البصمات -ثبوت إدانة املدعى عليه -وجود سوابق قضائية -تقرير بالسجن واجللد -أخذ تعهد بعدم تكرار الفعل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 34378220 :‬تاريخه‪1434/12/4 :‬هـ‬\n                     ‫رقم الدعوى‪34540463:‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34387980‬تاريخه‪1434/12/25 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة ســيارة ‪ -‬تقريــر فنــي البصمــات ‪ -‬ثبــوت إدانــة املدعــى‬\n‫عليــه ‪ -‬وجــود ســوابق قضائيــة ‪ -‬تقريــر بالســجن واجللــد ‪ -‬أخــذ تعهــد‬\n                                                      ‫بعــدم تكــرار الفعــل ‪.‬‬\n\n\n\n\n           ‫(أن التعزير يشرع يف كل معصية ال حد فيها وال كفارة )‪.‬‬\n\n\n\n\n‫دعــوى املدعــي العــام ضــد املدعــى عليــه بســرقة ســيارة أثنــاء وقوفهــا‬\n‫بإحــدى املواقــف ويطلــب إثبــات إدانتــه وتعزيــره شــرعا‪ ،‬باالطــاع علــى‬\n‫البــاغ املقــدم مــن املجنــي عليــه عــن تعــرض ســيارته للســرقة لــم يجدهــا‬\n‫وأفــاد أن الســيارة كانــت مفتوحــة األبــواب مــن الداخــل وبالبحــث عــن‬\n‫الســيارة املذكــورة عثــر عليهــا وقــد صــدر تقريــر فنــي بصمــات مــن‬\n‫األدلــة اجلنائيــة املتضمــن انطبــاق بصمــة الكــف األيســر للمدعــى عليــه‬\n‫علــى األثــر املرفــوع مــن الســيارة املســروقة املشــار إليهــا وباســتجواب‬\n‫املدعــى عليــه ومواجهتــه بانطبــاق بصماتــه علــى البصمــات املرفوعــة‬\n‫مــن الســيارة املشــار إليهــا لــم يذكــر مــا يبــرر ســبب وجــود بصماتــه‬\n‫علــى تلــك الســيارة وجــرى مضاهــاة بصمــات املتهــم املذكــور علــى‬\n‫القضايــا املقيــدة ضــد مجهــول واتضــح انطباقهــا علــى اآلثــار املرفوعــة‬\n\n                                                                                   ‫‪366‬‬\n\f      ‫مــن حادثتــي الســرقة مــن محــل عطــور وحادثــة ســرقة مكينــة خياطــة‪،‬‬\n      ‫أقــر املدعــى عليــه مبــا جــاء يف الدعــوى‪ ،‬ثبــوت اإلدانــة وصــدر احلكــم‬\n      ‫بجلــده ســتمائة جلــدة تقــع علــى بدنــه علــى اثنتــي عشــرة دفعــة متســاوية‬\n      ‫وبــن كل دفعــة و أخــرى عشــرة أيــام‪ ،‬وســجنه ســنة كاملــة ابتــداء مــن‬\n      ‫تاريــخ إيقافــه‪ ،‬وأن يؤخــذ عليــه التعهــد بعــدم العــودة ملثــل ذلــك‪ ،‬وقــرر‬\n      ‫املدعــى العــام االعتــراض وطلــب االســتئناف بــدون الئحــة وقــرر املدعــى‬\n                   ‫عليــه القناعــة‪ ،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫باملدينة املنورة وبناء على املعاملة احملالة لنا من فضيلة رئيس احملكمة‬\n      ‫اجلزائيــة باملدينــة املنــورة برقــم ‪ 34540463‬وتاريــخ ‪1434/12/02‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 342742767‬وتاريــخ ‪ 1434/12/02‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافق‪1434/12/03‬ه ـ افتتحــت اجللســة الســاعة ‪: 00‬‬\n      ‫‪09‬وفيهاحضراملدعــي العــام يف هيئــة التحقيــق واالدعــاء العــام باملدينــة‬\n      ‫املنــورة ‪ ....‬وادعــى علــى احلاضــر معــه يف مجلــس احلكــم ‪ ....‬ســعودي‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ....‬قائــا يف حتريــر دعــواه إنــه باالطــاع‬\n      ‫علــى البــاغ املقــدم مــن املواطــن ‪ .... /‬عــن تعــرض ســيارته نــوع ‪.....‬‬\n      ‫حتمــل اللوحــة رقــم ( ‪ ).....‬للســرقة عندمــا قــام بإيقافهــا أمــام مقهــى‬\n      ‫‪ ...........‬وعنــد خروجــه مــن املقهــى عنــد الســاعة الثالثــة والنصــف فجــر ًا‬\n      ‫لــم يجدهــا وأفــاد أن الســيارة كانــت مفتوحــة األبــواب مــن الداخــل‬\n      ‫وبالبحــث عــن الســيارة املذكــورة عثــر عليهــا بتاريــخ ‪1434/02/22‬ه ـ‬\n      ‫وقــد صــدر تقريــر فنــي بصمــات رقــم ‪1434 /44‬ه ـ مــن قبــل األدلــة‬\n\n‫‪367‬‬\n\f‫اجلنائيــة املتضمــن انطبــاق بصمــة الكــف األيســر للمدعــى عليــه علــى‬\n‫األثــر املرفــوع مــن الســيارة املســروقة املشــار إليهــا وباســتجوابه املدعــى‬\n‫عليــه ومواجهتــه بانطبــاق بصماتــه علــى البصمــات املرفوعــة من الســيارة‬\n‫املشــار إليهــا لــم يذكــر مــا يبــرر ســبب وجــود بصماتــه علــى تلك الســيارة‬\n‫وجــرى مضاهــاة بصمــات املتهــم املذكــور علــى القضايــا املقيــدة ضــد‬\n‫مجهــول واتضــح انطباقهــا علــى اآلثــار املرفوعــة مــن حادثتــي الســرقة‬\n‫مــن محــل عطــور عائــد للمواطــن ‪ ....‬وحادثــة ســرقة مكينــة خياطــة‬\n‫عائــدة للمواطــن ‪ .....‬مبحافظــة ‪ .....‬وقــد جــرى مخاطبــة شــرطة ‪ .....‬برقــم‬\n‫‪ 24/11237/22‬وتاريــخ ‪1434/11/09‬ه ـ للتحقيــق مــع املذكــور بتلــك‬\n‫القضايــا وعالقتــه بهــا كمــا جــرى إشــعار شــرطة ‪ ......‬باخلطــاب رقــم‬\n‫‪ 24/7093/22‬وتاريــخ ‪1434/11/11‬ه ـ املتضمــن إحالــة املتهــم للســجن‬\n‫العــام علــى ذمــة قضيــة ســرقة الســيارة وتقــرر توجيــه االتهــام للمدعــى‬\n‫عليــه بســرقة ســيارة أثنــاء وقوفهــا مبواقــف مقهــى ‪ .......‬وذلــك لألدلــة‬\n                                                                 ‫والقرائــن التاليــة ‪:‬‬\n‫‪ / 1‬مــا جــاء مبحضــر الدوريــات األمنيــة املتضمــن العثــور علــى الســيارة‬\n‫املرفــق لفــة (‪ / 2 )2‬مــا جــاء بالتقريــر الفنــي بصمــات رقــم ‪1434/44‬ه ـ‬\n‫املرفــق لفــة (‪ )16‬ووردت نتيجــة البحــث يف ســجل املدعــى عليــه اجلنائــي‬\n‫وتبــن وجــود ســابقة مســجلة عليــه األولــى ســرقة اســطوانة غــاز و ســابقة‬\n‫ثانيــة يف حيــازة واســتعمال مخــدرات وحيــث إن مــا أقــدم عليــه املدعــى‬\n‫عليــه فعــل محــرم ومعاقــب عليــه شــرعا أطلــب إثبــات مــا نســب إليــه‬\n‫أعــاه واحلكــم عليــه بعقوبــة تعزيريــة رادعــة لــه زاجــرة لغيــره لقــاء ذلــك‬\n‫علمــا أن احلــق اخلــاص مــازال قائمــا وهــو ســجني علــى ذمــة هــذه القضيــة‬\n‫منــذ تاريــخ ‪1434/10/26‬ه ـ هــذه دعــواي وبســؤال املدعــى عليــه عمــا‬\n\n\n                                                                                          ‫‪368‬‬\n\f      ‫جــاء يف دعــوى املدعــي العــام أجــاب قائــا مــا ذكــره املدعــي العــام‬\n      ‫يف دعــواه صحيــح جملــة وتفصيــا ففــي التاريــخ املذكــور يف الدعــوى‬\n      ‫ســرقت الســيارة املبينــة آنفــا حيــث كانــت واقفــة يف املــكان املذكــور‬\n      ‫آنفــا وقــد كانــت مفتحــة أبوابهــا فقمــت بتشــغيلها بطريقتــي وقدتهــا‬\n      ‫وكان فيهــا بعــض األغــراض لــم آخــذ منهــا شــيئ ًا وقــد تركتهــا بعــد‬\n      ‫اســتعمالها يف مــكان بعيــد وقــد قبــض علـ ّـي رجــال األمــن بعــد خمســة‬\n      ‫أيــام مــن حادثــة الســرقة ومســجل علــي ســابقة يف ســرقة أســطوانة غــاز‬\n      ‫وثانيــة يف حيــازة واســتعمال مخــدرات وقــد نلــت العقــاب عليهــا جميعــا‬\n      ‫ولــم أســرق شــيئا غيــر الســيارة وأنــا نــادم علــى فعلــي هــذا هكــذا أجــاب‬\n      ‫عقــب ذلــك قــال املدعــي العــام إن املدعــى عليــه متهــم بســرقة محــل و‬\n      ‫ســرقة مكينــة خياطــة وقــد فصلــت لهــا أوراق مســتقلة فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه صــادق علــى دعــوى‬\n      ‫املدعــي العــام فأقــر بســرقة الســيارة املذكــورة يف الدعــوى ومبــا أن‬\n      ‫الشــرع قــد حــرم التعــدي علــى أمــوال النــاس احملترمــة املقومــة بغيــر‬\n      ‫حــق ومبــا أن مــا أقــدم عليــه املدعــى عليــه فيــه زعزعــة لألمــن وإخافــة‬\n      ‫للنــاس علــى أموالهــم ومبــا أن املدعــى عليــه مــن أربــاب الســوابق وقــد‬\n      ‫نــال العقــاب عليهــا ولــم يرتــدع وهــذا يؤكــد ســوء مســلكه ومبــا أن‬\n      ‫التعزيــر يشــرع يف كل معصيــة ال حــد فيهــا وال كفــارة وهــو يختلــف‬\n      ‫باختــاف األحــوال واألشــخاص والزمــان واملــكان وتقديــر ذلــك راجــع‬\n      ‫لنظــر احلاكــم مبــا يــراه محققــا للزجــر والــردع جلميــع مــا ذكــر فقــد‬\n      ‫حكمــت بثبــوت إدانــة املدعــى عليــه مبــا نســب إليــه يف الدعــوى وقــررت‬\n      ‫تعزيــره علــى ذلــك للحــق العــام بجلــده ســتمائة جلــدة تقــع علــى بدنــه‬\n      ‫علــى اثنتــي عشــرة دفعــة متســاوية وبــن كل دفعــة و أخــرى عشــرة أيــام‬\n\n\n‫‪369‬‬\n\f‫ويســجن ســنة كاملــة ابتــداء مــن تاريــخ إيقافــه ويؤخــذ عليــه التعهــد‬\n‫بعــدم العــودة ملثــل ذلــك وبعرضــه قــرر املدعــى عليــه قناعتــه باحلكــم أمــا‬\n‫املدعــي العــام فقــرر عــدم قناعتــه باحلكــم وطلــب رفعــه إلــى محكمــة‬\n‫االســتئناف بــدون الئحــة اعتراضيــة فأجيــب لطلبــه وقــد انتهــت اجللســة‬\n‫يف متــام الســاعة ‪0 9: 30‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                      ‫وعلــى آلــه وصحبــه وســلم حــرر يف‪1434/12/03‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة االســتئناف‬\n                                                                      ‫يف منطقــة‬\n‫مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 342742767‬وتاريــخ‬\n‫‪1434/12/3‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪.... /‬‬\n‫القاضــي باحملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪34378220‬‬\n‫وتاريــخ ‪1434/12/4‬ه ـ املتضمــن دعــوى املدعــي العــام ضــد‪، .... /‬‬\n‫املتهــم يف ســرقه مــن داخــل ســيارة احملكــوم فيــه مبــا دون باطــن القــرار‬\n‫‪.‬وبدراســة القــرار وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم واهلل‬\n‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،،،،،‬‬\n\n\n\n\n                                                                                      ‫‪370‬‬\n\f                        ‫كشاف املوضوعات‬\n\n‫الصفحة‬                      ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n          ‫دعوى عامة ضد أشخاص ‪ :‬األول والثاني خلعا‬\n  ‫‪5‬‬        ‫ماكينة صراف آلي وجراها بواسطة سيارة‬              ‫سرقة‬     ‫‪1‬‬\n         ‫ومحاولة سرقة ما بداخلها والثالث تستر عليهما‬\n\n\n          ‫دعوى عامة ضد أشخاص لتكوينهم عصابة‬\n  ‫‪14‬‬       ‫لسرقة السيارات ؛ حيث قاموا بتنفيذ عدة‬            ‫سرقة‬     ‫‪2‬‬\n                           ‫سرقات‬\n\n\n         ‫دعوى عامة ضد شخص النتهاكه حرمة منزل‬\n  ‫‪69‬‬     ‫بالدخول إليه بالقفز على السور اخللفي وسرقة‬         ‫سرقة‬     ‫‪3‬‬\n                   ‫بعض محتويات املنزل‬\n\n\n           ‫دعوى عامة ضد عدة أشخاص أحدهم بالغ‬\n  ‫‪75‬‬                                                        ‫سرقة‬     ‫‪4‬‬\n         ‫والباقون قصر بسرقة سيارتني والتفحيط عليها‬\n\n\n          ‫دعوى عامة ضد أشخاص لتكوينهم عصابة‬\n          ‫نشل يف املسجد احلرام فاألول ينشل من زوار‬\n  ‫‪85‬‬                                                        ‫سرقة‬     ‫‪5‬‬\n         ‫املسجد والثاني يستلم املسروق ويخفيه والثالث‬\n                     ‫يراقب ويغطي عليهما‬\n\n\n          ‫دعوى عامة ضد ‪ 9‬مواطنني اتهم الرابع بسرقة‬\n         ‫سيارة وبيعها وقام األول والثاني والثالث بشرائها‬\n ‫‪112‬‬         ‫وقيادتها واخلامس والسادس والسابع بدور‬          ‫سرقة‬     ‫‪6‬‬\n          ‫الوساطة يف البيع وحضورهم مع الثامن والتاسع‬\n                        ‫ملشاهدة التفحيط‬\n\f‫الصفحة‬                    ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة ضد ‪ 3‬أشخاص فاألول اشترك يف‬\n          ‫سرقة حمام من مزرعة وجهاز هاتف محمول‬\n ‫‪127‬‬                                                   ‫سرقة‬     ‫‪7‬‬\n         ‫والثاني والثالث قفزا إلى داخل عدة مزارع مع‬\n                    ‫االشتراك يف السرقة‬\n\n\n          ‫دعوى عامة ضد مقيم بطريقة غير مشروعة‬\n         ‫لسرقته إبل من حوش صاحب اإلبل الذي يعمل‬\n ‫‪139‬‬                                                   ‫سرقة‬     ‫‪8‬‬\n           ‫لديه مبشاركة راعي اإلبل وشخص ثالث‬\n                   ‫وانتحاله لشخصية الغير‬\n\n\n         ‫دعوى عامة ضد شخص لكسره زجاج سيارة‬\n ‫‪145‬‬     ‫وسرقة حقيبة حتتوي أوراقا رسمية وبطاقات‬        ‫سرقة‬     ‫‪9‬‬\n                         ‫أحوال‬\n\n\n           ‫دعوى عامة ضد شخص لشروعه يف سرقة‬\n ‫‪152‬‬                                                   ‫سرقة‬     ‫‪10‬‬\n                  ‫كيابل من موقع شركة‬\n\n\n         ‫دعوى عامة ضد شخصني اشتركا يف سرقة‬\n          ‫أسالك نحاسية من مستودع بعد هتك احلرز‬\n ‫‪156‬‬                                                   ‫سرقة‬     ‫‪11‬‬\n          ‫والتستر مع شريكهما واشتراك الثاني يف‬\n                       ‫سرقة استراحة‬\n\n\n         ‫دعوى عامة ضد شخص باالشتراك مع هارب‬\n         ‫يف تكوين عصابة لسرقة السيارات وأجزائها‬\n ‫‪166‬‬                                                   ‫سرقة‬     ‫‪12‬‬\n           ‫واستغالل عمله يف الورشة لتحريف أرقام‬\n            ‫الهياكل وتركيبها على سيارات أخرى‬\n\n\n         ‫دعوى عامة ضد مواطن لسرقته سيارة وإحداث‬\n ‫‪183‬‬      ‫تلفيات بها والتصرف مبا كانت حتتويه من‬        ‫سرقة‬     ‫‪13‬‬\n                          ‫بضاعة‬\n\f‫الصفحة‬                    ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n          ‫دعوى عامة ضد مقيم يعمل يف ورشة لسرقته‬\n ‫‪193‬‬       ‫سيارتني ولوحة سيارة مبشاركة أشخاص‬            ‫سرقة‬     ‫‪14‬‬\n                    ‫آخرين تستر عليهم‬\n\n\n          ‫دعوى عامة ضد شخص ملشاركته يف سرقة‬\n ‫‪199‬‬                                                    ‫سرقة‬     ‫‪15‬‬\n               ‫مسجالت وسماعات من سيارات‬\n\n\n           ‫دعوى عامة ضد خمسة أشخاص يحملون‬\n ‫‪204‬‬       ‫بطاقات بديلة لسرقتهم مجموعة أغنام من‬         ‫سرقة‬     ‫‪16‬‬\n                         ‫حظيرة‬\n\n\n         ‫دعوى عامة ضد ثالثة أشخاص بتهمة االشتراك‬\n ‫‪211‬‬         ‫يف سرقة سيارة والتجول بها وإخفائها‬         ‫سرقة‬     ‫‪17‬‬\n                       ‫والتخطيط لذلك‬\n\n\n           ‫دعوى عامة ضد شخصني يحمالن بطاقتني‬\n           ‫بديلتني يف استالم سيارة من شخص لغرض‬\n ‫‪222‬‬                                                    ‫سرقة‬     ‫‪18‬‬\n          ‫تغسيلها فتركاها أمام املغسلة مما تسبب يف‬\n                          ‫سرقتها‬\n\n\n         ‫دعوى عامة ضد أشخاص فاألول والثاني اختلسا‬\n           ‫مبلغا ماليا من حساب عميل دون علمه واتهام‬\n ‫‪228‬‬      ‫الثالث والرابع واخلامس والسادس بإعطاء حرية‬    ‫سرقة‬     ‫‪19‬‬\n          ‫التصرف لألول بحساباتهم الشخصية مما سهل‬\n                           ‫االختالس‬\n\n\n           ‫دعوى عامة ضد شخص لسرقته طيرا من‬\n ‫‪256‬‬       ‫القفص من محل بيع طيور وإخفائه حتت‬            ‫سرقة‬     ‫‪20‬‬\n                         ‫مالبسه‬\n\f‫الصفحة‬                   ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة ضد مقيم لسرقته سيارة من أمام‬\n ‫‪261‬‬                                                  ‫سرقة‬     ‫‪21‬‬\n              ‫إحدى املطاعم وهي بوضع التشغيل‬\n\n\n          ‫دعوى عامة ضد أربعة أشخاص لتكوينهم‬\n ‫‪265‬‬       ‫عصابة سرقة من املعتمرين يف األماكن‬         ‫سرقة‬     ‫‪22‬‬\n                        ‫املزدحمة‬\n\n\n            ‫دعوى عامة ضد شخص لتكسيره زجاج‬\n ‫‪273‬‬     ‫سيارات وسرقة أربعة مسجالت فيها وكاميرا‬       ‫سرقة‬     ‫‪23‬‬\n                        ‫تلفزيونية‬\n\n\n          ‫دعوى عامة ضد شخص من أرباب السوابق‬\n ‫‪282‬‬                                                  ‫سرقة‬     ‫‪24‬‬\n           ‫بسرقة سيارة متوقفة أمام منزل صاحبها‬\n\n\n         ‫دعوى عامة ضد أربعة أشخاص فاألول سرق‬\n         ‫سيارة وتصرف بها بتشليحها واشتراك الثاني‬\n ‫‪286‬‬                                                  ‫سرقة‬     ‫‪25‬‬\n         ‫والثالث يف تشليحها وتسترهما مع الرابع على‬\n                           ‫األول‬\n\n\n         ‫دعوى عامة ضد شخص لسرقته من منزل جاره‬\n ‫‪294‬‬      ‫ومحاولة تضليل جهة التحقيق بادعاء تعرضه‬      ‫سرقة‬     ‫‪26‬‬\n                        ‫لسرقة جواله‬\n\n\n         ‫دعوى عامة ضد شخص لسلبه سيارة شخص‬\n ‫‪299‬‬                                                  ‫سرقة‬     ‫‪27‬‬\n                      ‫والفرار بها‬\n\n\n         ‫دعوى عامة ضد شخص حملاولته كسر الباب‬\n ‫‪303‬‬                                                  ‫سرقة‬     ‫‪28‬‬\n            ‫اخلارجي إلحدى األسواق بقصد سرقته‬\n\f‫الصفحة‬                     ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n          ‫قدم شيكا‬ ‫دعوى عامة ضد أشخاص فاألول ّ‬\n ‫‪310‬‬     ‫مزورا إلحدى املؤسسات والثاني حليازة وبيع عدد‬    ‫سرقة‬     ‫‪29‬‬\n            ‫أربع سبائك ذهب والثالث خليانة األمانة‬\n\n\n         ‫دعوى عامة ضد شخص الشتراكه مع آخر يف‬\n ‫‪326‬‬                                                     ‫سرقة‬     ‫‪30‬‬\n                     ‫نشل حقيبة امرأة‬\n\n\n         ‫دعوى عامة ضد شخص يعمل خفيرا لتمكينه‬\n ‫‪331‬‬     ‫شخص ًا من سرقة ماكينة واسطة بحرية تابعة‬         ‫سرقة‬     ‫‪31‬‬\n                  ‫حلرس احلدود مقابل مبلغ مالي‬\n\n\n          ‫دعوى عامة ضد شخص لقيامه بسرقة أموال‬\n ‫‪337‬‬                                                     ‫سرقة‬     ‫‪32‬‬\n                  ‫وأجهزة وغيرها من شركة‬\n\n\n         ‫دعوى عامة ضد شخص يعمل مسؤول صندوق‬\n ‫‪349‬‬                                                     ‫سرقة‬     ‫‪33‬‬\n             ‫باختالس مبلغ مالي من خزنة مجمع‬\n\n\n          ‫دعوى عامة ضد شخص لسرقته حافظة نقود‬\n ‫‪355‬‬                                                     ‫سرقة‬     ‫‪34‬‬\n                         ‫من سيارة‬\n\n\n          ‫دعوى عامة ضد شخص لدخوله منزال وسرقة‬\n ‫‪360‬‬                                                     ‫سرقة‬     ‫‪35‬‬\n                 ‫مبلغ مالي منه وجهازي جوال‬\n\n\n          ‫دعوى عامة ضد شخص لسرقته سيارة أثناء‬\n ‫‪366‬‬                                                     ‫سرقة‬     ‫‪36‬‬\n                     ‫وقوفها بإحدى املواقف‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":366,"source_page_end":375,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"70e4598fa01906196247b4b811651f2095fedb44f8e1f8c1dcc1aef15973e75d","normalized_text_hash":"4b81b7ab4386e3b059d3be60652fbf7dd9d79a698a096e52a8d27a8b5290d80c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p366-34378220"},{"id":"70de9b95-c505-56cd-8153-87d39aa79b57","document_type":"judgment","category":"judicial","subcategory":"general","title":"خيانة أمانة -عجز يف عهدة العامل -إنكار الدعوى -صرف النظر عن دعوى املدعي العام لعدم ثبوتها.","document_number":"34312068","case_number":"4579","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/09/03","year":"1434","subject":"خيانة أمانة -عجز يف عهدة العامل -إنكار الدعوى -صرف النظر عن دعوى املدعي العام لعدم ثبوتها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫رقم الصك‪ 34312068 :‬تاريخه‪1434/09/03 :‬هـ‬\n                            ‫رقم الدعوى‪4579 :‬‬\n           ‫قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34356932‬تاريخه‪1434/11/11 :‬هـ‬\n\n\n     ‫خيانــة أمانــة ‪ -‬عجــز يف عهــدة العامــل ‪ -‬إنــكار الدعــوى ‪ -‬صــرف النظــر‬\n                                          ‫عــن دعــوى املدعــي العــام لعــدم ثبوتهــا‪.‬‬\n\n\n\n\n                                        ‫ما أشار إليه القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n           ‫تقــدم ملركــز الشــرطة وكيــلٌ شــرعي إلحــدى املؤسســات ببـ ٍ‬\n     ‫ـاغ عــن‬\n     ‫مكفــول املؤسســة (املدعــى عليــه) مفــاده أنــه خــان األمانــة‪ ،‬وقــام بأخــذ‬\n     ‫مبلــغ مالــي أثنــاء عملــه مندوبــا للمبيعــات يف املؤسســة ‪ ،‬بالتحقيــق مــع‬\n     ‫املدعــى عليــه اعتــرف بوجــود العجــز لديــه باملبلــغ املشــار إليــه مــن خــال‬\n     ‫بيعــه للبضائــع يف احملــات وأنــه املســؤول عن ذلك املبلــغ وصدق اعترافه‬\n     ‫شــرعا ‪ ،‬مت توجيــه االتهــام لــه بخيانــة األمانــة ‪ ،‬بالبحــث عــن ســوابقه‬\n     ‫لــم يعثــر لــه علــى ســوابق مســجلة ‪ ،‬طلــب املدعــى العــام احلكــم عليــه‬\n     ‫بعقوبــة تعزيريــة لقــاء خيانتــه لألمانــة ‪ .‬بعــرض ذلــك علــى املدعــي عليــه‬\n     ‫أنكــر اخليانــة‪ ،‬وأفــاد أن ســبب هــذا العجــز أنــه اســتلم مــن املؤسســة‬\n     ‫مــواد غذائيــة وقــام بتصريفهــا باألجــل ويأخــذ علــى ذلــك عمولــة ورمبــا‬\n     ‫بــاع بأقــل مــن القيمــة ألجــل العمولــة فحصــل العجــز وأنــه صــدر حكـ ٌـم‬\n     ‫يف احلــق اخلــاص ُيلزمــه بتســليم املبلــغ ‪ ،‬جــرى االطــاع علــى صــك احلكم‬\n‫‪5‬‬\n\f‫يف احلــق اخلــاص ‪ ،‬كمــا جــرى االطــاع علــى إقرار املدعــى عليه املصدق‬\n‫عليــه شــرعا ‪ ،‬نظــر ًا إلــى أن إقــرار املدعــى عليــه وجوابــه ليــس فيــه مــا‬\n‫يثبــت إدانتــه مبــا اتهــم بــه مــن االختــاس وخيانــة األمانــة لــذا مت احلكــم‬\n‫بصــرف النظــر عــن دعــوى املدعــي العــام لعــدم ثبوتهــا ‪ ،‬بعــرض احلكــم‬\n‫علــى الطرفــن قــرر املدعــي العــام عــدم القناعــة وطلــب رفــع احلكــم‬\n‫إلــى محكمــة االســتئناف مكتفيــا بالئحــة الدعــوى العامــة وبعــد رفــع‬\n                        ‫احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 4579‬وتاريــخ ‪ 1431/02/15‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 3114570‬وتاريــخ ‪ 1431/02/15‬ه ـ ففــي يــوم‬\n‫اخلميــس املوافــق‪ 1434/09/03‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 45‬‬\n‫وفيهــا حضــر ‪ ...‬وقــال بصفتــي مدعيــا عامــا بدائــرة االدعــاء العــام بدائرة‬\n‫الريــاض ادعــي ‪ 56 ...‬ســنة مينــي اجلنســية يحمــل إقامــة رقــم ‪ ...‬موقــف مــن‬\n‫تاريــخ ‪1431/1/9‬ه ـ حيــث أنــه بتاريــخ ‪1430/11/15‬ه ـ تقــدم مركــز‬\n‫شــرطة العزيزيــة وكيــل شــرعي ملؤسســة ‪ ...‬ببــاغ عــن مكفولهــم‬\n‫املذكــور أنــه خــان األمانــة وقــام باختــاس مبلــغ قــدره ثالثمئــة واربعــة‬\n‫وعشــر ألــف وخمســمئة وســتون ريــال حيــث يعمــل يف املؤسســة مندوبــا‬\n‫للمبيعــات وقــدم للوكيــل الشــرعي تقريــر ًا مــن محاســب قانونــي يثبــت‬\n‫ذلــك وبالتحقيــق معــه اعتــرف بوجــود العجــز لديــه باملبلــغ املشــار إليــه‬\n‫مــن خــال بيعــه للبضائــع يف احملــات وأنــه املســؤول عــن ذلــك املبلــغ‬\n\n                                                                                       ‫‪6‬‬\n\f    ‫وصــدق اعترافــه شــرعا وقــد أســفر التحقيــق عــن توجيــه االتهــام لــه‬\n    ‫بخيانــة األمانــة لوجــود عجــز مبلــغ مالــي قــدره ثالثمئــة واربعــة وعشــر‬\n    ‫ألــف وخمســمئة وســتون ريــال وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى‬\n    ‫ســوابق مســجلة وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب‬\n    ‫عليــه لــذا أطلــب احلكــم عليــه بعقوبــة تعزيريــة لقــاء مــا أســند إليــه علمــا‬\n    ‫بــأن احلــق اخلــاص مــا زال قائمــا وبــاهلل التوفيــق هــذا وقــد حضــر املدعــى‬\n    ‫عليــه ‪ ....‬معــه بطاقــة نزيــل برقــم ‪2/31/92‬س صــادرة مــن مديــر ســجن‬\n    ‫امللــز وجــرى عــرض الئحــة املدعــي العــام ضــده عليــه فأجــاب قائــا قــد‬\n    ‫صــدر علــي حكــم مــن احملكمــة العامة بدفع مبلغ قــدره ثالثمئة وأربعة‬\n    ‫عشــر ألــف وخمســمئة وواحــد وســتون ريــاال وذلــك لصالــح املؤسســة التي‬\n    ‫كنــت أعمــل فيهــا وهــي مؤسســة ‪ ...‬وكان ســبب هــذا املبلغ أنني أســتلم‬\n    ‫مــن املؤسســة مــواد غذائيــة حلــوم مجمــدة وخضــار وأقــوم بتصريفهــا‬\n    ‫باألجــل ثــم بعــد ذلــك حصــل عنــدي عجــز مالــي نتيجــة أن اســتالمي مــن‬\n    ‫املؤسســة باحلــال وتصريفــي لهــا يكــون باآلجــل وآخــذ علــى ذلــك عمولــة‬\n    ‫مــن املؤسســة فكنــت أســتعجل البيــع باآلجــل رمبــا كان مببلــغ أقــل‬\n    ‫مــن أجــل العمولــة ثــم قــال أنــا موقــف علــى ذمــة تســديد هــذا املبلــغ الــذي‬\n    ‫حكمــه بــه علــي قبــل نحــو ثــاث ســنوات ثــم جــرى تصفــح أوراق املعاملــة‬\n    ‫فوجــدت مــن ضمنهــا احلكــم الصــادر مــن احملكمــة العامــة بالريــاض‬\n    ‫علــى املدعــى عليــه بدفــع املبلــغ املذكــور لصالــح مؤسســة ‪ ...‬وهــو برقــم‬\n    ‫‪ 32232057‬بتاريــخ ‪1432/9/7‬ه ـ وقــد ورد بدعــوى باحلــق اخلــاص علــى‬\n    ‫املدعــى عليــه مــا نصــه (إن املدعــى عليــه يعمــل لــدى موكلــي بوظيفــة‬\n    ‫منــدوب مبيعــات وقــد اتضــح أن لديــه عجــز مالــي وقــدره ثالثمئــة وواحــد‬\n    ‫وعشــرون ألــف وخمســمئة وواحــد وســبعون ريــاال) أ‪.‬ه ـ فكانــت اإلجابــة‬\n\n\n‫‪7‬‬\n\f‫املصادقــة علــى ذلــك بعــد تعديــل املبلــغ ثــم انتهــى النظــر الشــرعي بإلــزام‬\n‫املدعــى عليــه بدفــع املبلــغ املذكــور وقــد اكتســب احلكــم القطعيــة‬\n‫بقناعــة الطرفــن ثــم جــرى ســؤال املدعــي العــام عــن بينته فقــال اعتراف‬\n‫املدعــى عليــه املصــدق شــرعا يف الصحيفــة رقــم ‪ 15‬مــن ملــف التحقيــق‬\n‫املرفــق باملعاملــة وباالطــاع عليــه ألفيــت نصــه (نعــم أنــا ‪ ...‬مينــي اجلنســية‬\n‫‪ 51‬عامــا أنــه أثنــاء عملــي مبؤسســة ‪ ...‬التجاريــة كمنــدوب مبيعــات‬\n‫اتضــح أنــه يوجــد يف ذمتــي مبلــغ مالــي وقــدره ثالثمئــة وأربعــة عشــر ألــف‬\n‫وخمســمئة وواحــد وســتون ريــال وهــي قيمــة بضائــع تبــاع بقيمــة آجــل‬\n‫الدفــع بعــد دفعهــا وبيعهــا وهــي حتــت مســؤوليتي ويف ذمتــي هــذا إقراري‬\n‫) وقــد صــدق هــذا اإلقــرار مــن قبــل فضيلــة رئيــس احملكمــة بتاريــخ‬\n‫‪1431/1/11‬ه ـ ثــم قــال املدعــي العــام بينتــي الثانيــة يف تقريــر احملاســب‬\n‫القانونــي ثــم جــرى تصفــح أوراق املعاملــة فلــم أجــد مــن ضمنهــا هــذا‬\n‫التقريــر وســألت املدعــي العــام عنــه فقــال ليــس لــدي غيــر مــا يف أوراق‬\n‫املعاملــة ثــم جــرى ســؤال املدعــى عليــه فقــال ليــس لــدي غيــر مــا قلــت‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث إن التقاريــر الســابقة‬\n‫الصــادرة مــن املدعــى عليــه املتمثلــة يف إقــراره املصــدق شــرع ًا املرصــود‬\n‫بعاليــه وكــذا الدعــوى باحلــق اخلــاص عليــه مــع إقــراره هــذا اليــوم لدينــا‬\n‫إنــه ليــس يف ذلــك مــا يثبــت إدانتــه مبــا أتهــم بــه مــن االختــاس وخيانــة‬\n‫األمانــة بــل الغايــة ومــا فيهــا عجــز مالــي أثنــاء العمــل لــذا فقــد صرفــت‬\n‫النظــر عــن طلــب املدعــي العــام وبذلــك حكمــت وبتــاوة احلكــم علــى‬\n‫الطرفــن قــرر املدعــي العــام عــدم القناعــة وطلــب رفــع احلكــم إلــى‬\n‫محكمــة االســتئناف مكتفيــا بالئحــة الدعــوى العامــة واقفــل احملضــر‬\n‫الســاعة ‪ 12.45‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n\n\n                                                                                         ‫‪8‬‬\n\f                                    ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/9/3‬ه ـ‬\n    ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n    ‫األولــى مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n    ‫رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪ 341992022‬وتاريــخ‬\n    ‫‪1434/10/22‬ه ـ واملرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n    ‫باحملكمــة‪ ... /‬برقــم ‪ 34312068‬وتاريــخ ‪1434/9/3‬ه ـ واخلــاص‬\n    ‫بدعــوى املدعــي العــام ضــد‪»... /‬مينــي اجلنســية»‪ ،‬وموضوعهــا قضيــة‬\n    ‫خيانــة أمانــة وانتهــاء الدراســة والتدقيــق املصادقــة علــى احلكــم لعــدم‬\n    ‫موجــب املالحظــة مــع تنبيــه فضيلتــه إلــى تدويــن كلمــة (ابــن) يف اســم‬\n    ‫فضيلتــه يف بــدء القــرار ويف ختامــه ‪،‬ورصــد اســم املدعــي العــام الثالثــي‬\n    ‫حتــت توقيعــه يف الضبــط حســب التعليمــات وتصحيــح األخطــاء املعلــم‬\n    ‫ال واهلل املوفــق وصلــى‬ ‫عليهــا بقلــم الرصــاص ومالحظــة ذلــك مســتقب ً‬\n                    ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــة وســلم ‪.‬‬\n\n\n\n\n‫‪9‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":5,"source_page_end":9,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5f4618e6b6fcfb1ae956a228be5fd138be05ca9d0156e43ff555cd968c1c4254","normalized_text_hash":"07989f4c63758b3c46fd15eff6db7439569e62b0ac9d38304c44781e425a604b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p5-34312068"},{"id":"b64ea314-84ce-5016-b73b-15788b1aae39","document_type":"judgment","category":"judicial","subcategory":"general","title":"خيانة أمانة -أخذ املدعى عليه عليهما مبلغ مالي من الشركة التي يعمان بها -إقرار -إثبات إدانة بخيانة األمانة -تغليظ العقوبة -التعزير بالسجن واجللد .","document_number":"34227186","case_number":"3455426","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/29","year":"1434","subject":"خيانة أمانة -أخذ املدعى عليه عليهما مبلغ مالي من الشركة التي يعمان بها -إقرار -إثبات إدانة بخيانة األمانة -تغليظ العقوبة -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34227186 :‬تاريخه‪1434/5/29 :‬هـ‬\n                    ‫رقم الدعوى‪3455426 :‬‬\n       ‫قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34263495‬تاريخه‪1434/7/9:‬هـ‬\n\n\n‫خيانــة أمانــة ‪ -‬أخــذ املدعــى عليــه عليهمــا مبلــغ مالــي مــن الشــركة‬\n‫التــي يعمــان بهــا ‪ -‬إقــرار ‪ -‬إثبــات إدانــة بخيانــة األمانــة ‪ -‬تغليــظ‬\n                                ‫العقوبــة ‪ -‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n    ‫‪ -‬قول اهلل تعالى‪( :‬إن اهلل يأمركم أن تؤدوا األمانات إلى أهلها) ‪.‬‬\n\n\n\n\n‫توجيــه االتهــام للمدعــى عليهمــا بخيانــة األمانــة وأخــذ مبلــغ مالــي مــن‬\n‫الشــركة التــي يعمــان فيهــا ‪ -‬بالبحــث عــن ســوابقهما لــم يعثــر لهمــا‬\n‫على سوابق‪ -‬طلب املدعي العام إثبات ما أسند إليهما واحلكم عليهما‬\n‫بعقوبــة تعزيريــة ‪ -‬بعــرض دعــوى املدعــي العــام علــى املدعــى عليهمــا أقــر‬\n‫ا ومعقب ـ ًا يف الشــركة املدعيــة باحلــق اخلــاص‬    ‫األول أنــه يعمــل مراس ـ ً‬\n‫وأنــه أخــذ مــن أموالهــا ســتني ألــف ريــال وأخفاهــا وأنــه ليــس للمدعــى‬\n‫عليــه الثانــي أي عالقــة يف أخــذ أمــوال الشــركة‪ ،‬وأجــاب املدعــى عليــه‬\n‫الثانــي أنــه يعمــل يف الشــركة املدعيــة باحلــق اخلــاص مراســا وليــس لــه‬\n‫عالقــة باختــاس األمــوال ‪ -‬جــرى االطــاع علــى أقــوال املدعــى عليــه‬\n‫الثانــي حتقيق ـاً‪ ،‬وعلــى إقــراره املصــدق شــرعا‪ ،‬وبعرضــه عليــه ذكــر‬\n‫أنــه وقــع عليــه دون أن يقــرأه وصــادق عليهــا‪ -‬نظــر ًا إلقــرار املدعــى عليــه‬\n                                                                                       ‫‪10‬‬\n\f     ‫األول مبــا جــاء يف الدعــوى وإقــرار املدعــى عليــه الثانــي بأخــذه مبلــغ‬\n     ‫ســتني ألــف ريــال مــن أمــوال الشــركة وأنــه هــو املبلــغ الوحيــد الــذي‬\n     ‫ســحبه منهــا لوجــود حســاب خــاص بالشــركة وإلقــرار املدعــى عليــه‬\n     ‫الثانــي بإرجاعــه املبلــغ يف يــوم احلادثــة ولظهــور اخليانــة بتصــرف املدعــى‬\n     ‫عليهمــا املذكــور ومشــروعية التعزيــر عليــه ‪ ،‬لــذا ثبتــت إدانــة املدعــى‬\n     ‫عليهمــا بخيانــة األمانــة وأخــذ مبلــغ مالــي مــن الشــركة ومت احلكــم‬\n     ‫عليهمــا مبــا يلــي ‪ /1 :‬ســجن املدعــى عليــه األول ثالثــون شــهرا وجلــده‬\n     ‫ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات ‪ /2‬ســجن املدعــى عليــه الثانــي‬\n     ‫ســنة وجلــده مائــة وعشــرين جلــدة مفرقــة علــى دفعتــن كل دفعــة ســتون‬\n     ‫جلــدة واجللــد أمــام النــاس ‪ -‬بعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n     ‫عليهمــا القناعــة وقــرر املدعــي العــام االعتــراض مكتفيــا بالئحــة‬\n     ‫الدعــوى‪ ،‬وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزائيــة بالريــاض برقــم ‪ 3455426‬وتاريــخ ‪ 1434/02/03‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 34275988‬وتاريــخ ‪ 1434/02/03‬ه ـ ففــي يــوم‬\n     ‫الســبت املوافق‪ 1434/03/14‬هـ افتتحت اجللســة الســاعة ‪10 : 00‬وفيها‬\n                   ‫قــدم املدعــي العــام ‪.....‬الئحــة دعــوى عامــة ضــد كل مــن ‪/‬‬\n     ‫‪ 26..... .1‬ســنة ســعودي اجلنســية ســجل مدني رقم (‪ ).....‬موقوف مبوجب‬\n                          ‫مذكرة التوقيف رقم (‪ ).....‬وتاريخ‪1433/11/28‬هـ ‪.‬‬\n     ‫‪ 25..... .2‬ســنة ميانــي اجلنســية مبوجــب رخصــة اإلقامة رقــم (‪ ).....‬موقوف‬\n‫‪11‬‬\n\f                 ‫مبوجب مذكر ة توقيف رقم (‪.....‬وتاريخ‪1433/11/28‬هـ ‪.‬‬\n‫بتاريــخ ‪1433/10/28‬ه ـ حضــر ملركــز شــرطة ‪.....‬األول مبلغ ـ ًا بانــه‬\n‫أثنــاء خروجــه مــن مكتــب فــرع ‪.....‬للتأمــن والــذي يعمــل بهــا بحــي‬\n‫‪.....‬علــى ســيارته مــن نــوع ‪ ......‬ومعــه ظــرف أبيــض بداخلــه مبلــغ مالــي‬\n‫وقــدره (‪ )144710‬مائــة وأربعــة وأربعــون ألــف وســبعمائة وعشــرة‬\n‫ريــاالت وشــيكني األول صــادر مــن البنــك ‪ ..........‬بقيمــة (‪ )15728‬ريــال‬\n‫والثانــي شــيك مــن البنــك ‪ ...........‬بقيمــة (‪ )10726‬ريــال وعنــد وصولــه‬\n‫إلــى شــارع ‪ .....‬مــع طريــق ‪ .....‬وأمــام مطعــم ‪ .....‬قــام صاحــب ســيارة مــن‬\n‫نــوع كابــرس اللــون أســود مظللــة بالكامــل (ال يعــرف رقــم اللوحــة)‬\n‫بالتوقــف خلفــه وأثنــاء ذلــك نــزل شــخص أســود البشــرة بكســر زجــاج‬\n‫ســيارة املبلــغ وضربــه مبفــك علــى يــده اليســرى ونــزل صاحــب الســيارة‬\n‫‪ .......‬وهــو اســود البشــرة وقــام بفتــح بــاب الراكــب وأخــذ الظــرف مــن‬\n‫حتــت املرتبــة األولــى والهــرب علــى الســيارة وقيــام األخــر بالهــرب مــع‬\n‫صاحــب الســيارة الكابــرس و ادعــى أنــه قــام مبالحقتهــم حتــى الوصول‬\n‫حلــي ‪.....‬ولــم يتمكــن مــن القبــض عليهــم ونتــج عــن ذلــك إصابتــه بجــرح‬\n‫يف الســاعد األيســر ‪.‬ولعــدم قناعــة جهــة التحقيــق يف صحــة البــاغ (مت‬\n‫التحفــظ علــى املبلــغ يف حينــه) واعتــرف علــى زميلــه الثانــي والــذي مت‬\n                            ‫القبــض عليــه مــن قبــل وحــدة البحــث باملركــز ‪.‬‬\n‫وجــرى االنتقــال رفــق األول الســتراحته الواقعــة بحي ‪.....‬وقام باســتخراج‬\n‫مبلــغ (‪ )858536‬خمســة وثمانــون ألــف وخمســمائة وســتة وثالثــون ريــال‬\n   ‫والشــيكان التــي قــام بســرقتها والعائــدة لشــركة الــذي يعملــون بهــا ‪.‬‬\n‫وبضبط إفادة ‪..... /‬أفاد بأنه جرى تسليم األول مبلغ وقدره (‪)144710‬‬\n‫مائــة وأربعــة وأربعــون ألــف وســبعمائة وعشــرة ريــاالت وشــيكان تخــص‬\n\n\n                                                                                      ‫‪12‬‬\n\f     ‫‪.....‬لتأمــن ولــم يقــم بإيداعهــا وأنــه مــن املفتــرض قيامــه بالذهــاب رفــق‬\n     ‫الثانــي وقــد طلــب مــن زميلــه عــدم مرافقتــه حســب أفادتــه وقــد تأخــر يف‬\n                                                      ‫بالغــه ويشــك يف صحــة بالغــه ‪.‬‬\n     ‫وباســتجواب األول أعتــرف أن جميــع مــا ذكــره غيــر صحيــح وأنــه‬\n     ‫أختلــق تلــك القصــة لســرقة املبلــغ حيــث أقــر بقيامــه باســتالم املبلــغ‬\n     ‫وطلــب مــن زميلــه الثانــي عــدم مرافقتــه وقــام بالذهــاب إلــى اســتراحة‬\n     ‫بحــي ‪.....‬وإخفــاء املبلــغ والشــيكان املســروقة والتمثيــل بكســر زجــاج‬\n     ‫ســيارته أمــام االســتراحة والذهــاب إلــى حــي ‪.....‬ومقابلــة زميلــه الثانــي‬\n     ‫وتســليمه مبلــغ ســتون ألــف ريــال مــن املبلــغ الــذي أخــذه مــن الشــركة‬\n     ‫وأضــاف انــه اجتــه ملركــز الشــرطة لتقــدمي بــاغ كاذب ‪.‬وباســتجواب‬\n     ‫الثانــي ذكــر بأنــه خــرج مــع زميلــه األول مــن الشــركة بعــد اســتالمه‬\n     ‫مبلــغ وقــدره (‪ )144710‬مائــة وأربعــة وأربعــون ألــف وســبعمائة وعشــرة‬\n     ‫ريــاالت وشــيكان عائــدة للشــركة لغــرض إيداعهــا وعندهــا طلــب منــه‬\n     ‫زميلــه األول أن ال يرافقــه للبنــك وذهــب لوحــده لبنــك ‪ ...........‬إليــداع‬\n     ‫مبالــغ ماليــة وبعــد خروجــه مــن البنــك ‪ ...........‬قــام باالتصــال علــى زميلــه‬\n     ‫األول علــى هاتفــه وأفــاد بأنــه يطــارده أشــخاص قامــوا بســرقته وقابلــه‬\n     ‫بحــي ‪.....‬وذكــر لــه احلادثــة وقــام بــدوره بإبــاغ دوريــات األمــن وأنــه ليــس‬\n     ‫لديــه مــا يضيفــه (وبعــد اعتــراف زميلــه بتســليمه مبلــغ ســتون ألــف ريــال‬\n     ‫مــن املبلــغ املســروق) اعتــرف مبقابلــة األول واســتالم منــه مبلــغ ســتون‬\n     ‫ألــف ريــال والتــي ســبق وأن أخذهــا مــن الشــركة وأعطــاه لــه وأضــاف‬\n     ‫بــأن الشــركة قامــت بطلــب املبلــغ منــه بنفــس يــوم احلادثــة (ممــا يؤكــد‬\n     ‫أنــه خطــط مــع زميلــه املدعــى عليــه األول) وقــام بطلــب املبلــغ مــن زميلــه‬\n     ‫والــذي قــام بتســليم املبلــغ لــه ومــن ثــم قــام هــو بــدوره بإعادتــه لشــركة‪.‬‬\n\n\n‫‪13‬‬\n\f‫)مت معاجلــة موضــوع البــاغ الــكاذب مــن قبــل اجلهــة املختصــة(‪ .‬وقــد‬\n‫أســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليهمــا بخيانــة األمانــة‬\n                       ‫وأخــذ مبلــغ مالــي وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n‫‪ /1‬اعتــراف األول والثانــي املــدون صفحــة (‪ )14.8‬مــن دفتــر التحقيــق‬\n                                                            ‫املرفــق داخــل الطــرد‬\n‫‪ /2‬محضــر االنتقــال واملعاينــة علــى مــكان املبالــغ والشــيكات املرفــق‬\n                                             ‫‪.‬‬                       ‫داخــل الطــرد‬\n                  ‫‪ /3‬إفادة ‪ ..... /‬واملدون يف دفتر التحقيق املرفق بالطرد ‪.‬‬\n                                 ‫وببحث سوابقهما لم يعثر لهما على سوابق ‪.‬‬\n‫وحيــث أن مــا أقــدم عليــه املدعــى عليهمــا فعــل محــرم ومعاقــب عليــه‬\n‫شــرعا أطلــب إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بعقوبــة تعزيريــة‬\n                                   ‫(علم ـ ًا بــأن احلــق اخلــاص انتهــى بالتنــازل) ‪.‬‬\n‫هــذه دعــواي علــى املدعــى عليهمــا وقــد أجــاب املدعــى عليــه ‪ ....‬قائــا‬\n‫إن مــا ذكــره املدعــي العــام يف الدعــوى غيــر صحيــح إال فيمــا ذكــر يف‬\n‫مبلــغ الســتني ألــف والصحيــح أننــي أعمــل مراســا ومعقبــا يف شــركة‬\n‫‪.....‬لوكالــة التأمــن وصاحبهــا ‪.....‬وقــد أخــذت مــن أموالهــا املبالــغ‬\n‫املذكــورة وقمــت بإخفائهــا يف اســتراحتي كمــا ذكــر واختلقــت‬\n‫قصــة الســرقة املذكــورة وليــس للمدعــى عليــه ‪.....‬أي عالقــة يف أخــذ‬\n‫أمــوال الشــركة بــل أحتملهــا لوحــدي وقــد أقرضنــي ســتني ألــف ريــال‬\n‫وســلمته إياهــا وقلــت يف التحقيــق إنهــا مــن أمــوال الشــركة واحلقيقــة‬\n‫أنهــا مــن أموالــي هكــذا أجــاب وأجــاب املدعــى عليــه ‪.....‬إننــي أعمــل‬\n‫يف شــركة ‪.....‬لوكالــة التأمــن مراســا وليــس لــي عالقــة باختــاس‬\n‫األمــوال وقــد أبلغنــي املدعــى عليــه ‪.....‬بتعرضــه للســطو مــن قبــل شــخص‬\n\n\n                                                                                          ‫‪14‬‬\n\f     ‫أخــذ مــال الشــركة منــه وقــد رأيــت زجــاج ســيارته مكســورا وبــه‬\n     ‫إصابــات فاتصلــت وأخبــرت الشــرطة وقــد ســلمني ســتني ألــف ريــال‬\n     ‫قرضــة حســنة ســلمتها لــه وقمــت بإرجاعهــا للشــركة ألنهــا وديعــة لــدي‬\n     ‫والشــركة تســتخدم حســابي يف اإليــداع والتحويــل ولــم أقــم بســرقة‬\n     ‫شــيء مــن أموالهــا هكــذا أجــاب وباالطــاع علــى أوراق املعاملــة ألفيــت‬\n     ‫أقــوال املدعــى عليــه ‪.....‬علــى ص‪ 4‬مــن آخــر ملــف يف التحقيــق يف الطــرد‬\n     ‫املرفــق باملعاملــة واملتضمــن إقــراره بســحب ســتني ألــف ريــال مــن حســاب‬\n     ‫الشــركة قبــل وقــوع احلادثــة بأســبوعني وقــد طلبــت الشــركة تســليم‬\n     ‫املبلــغ يف نفــس يــوم احلادثــة وعلــى ص‪ 5‬أنــه أعطــى هــذا املبلــغ للمدعــى‬\n     ‫عليــه ‪.....‬وأن ‪.....‬أرجــع لــه هــذا املبلــغ وأنــه قــام بإرجاعــه للشــركة‬\n     ‫إ‪.‬ه ـ وذلــك مرصــود يف إقــراره املصــدق شــرعا علــى ص‪ 3-2‬مــن امللــف‬\n     ‫الثانــي للتحقيــق وبعرضــه عليــه قــال وقعــت عليــه دون أن أقرأهــا وهــي‬\n     ‫صحيحــة ثــم جــرى ســؤال املدعــى عليــه كــم عــدد املبالــغ التــي أخذتهــا‬\n     ‫مــن الشــركة فقــال ســتون ألــف ريــال فقــط ثــم جــرى ســؤاله هــل‬\n     ‫يوجــد إثبــات ذلــك أن الشــركة تــودع يف حســابك فقــال نعــم كشــف‬\n     ‫حســاب وقــدم صــورة كشــف حســاب باســمه يف البنــك ‪...................‬‬\n     ‫ولــم يوجــد فيــه ذكــر للشــركة وإمنــا حتويــل مــن احلســاب للشــركة‬\n     ‫‪.....‬للتأمــن فقــال إن األمــوال تــودع بأســماء مندوبــي الشــركة فجــرى‬\n     ‫ســؤال املدعــى عليهمــا أيــن تودعــون أمــوال الشــركة فقــاال يف حســابها‬\n     ‫وهــو نفــس حســاب الشــركة ‪.....‬للتأمــن ألن الشــركة التــي نعمــل فيهــا‬\n     ‫مــن فروعهــا هكــذا أجابــا فبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة‬\n     ‫وإلقــرار املدعــى عليــه ‪.....‬مبــا جــاء يف الدعــوى وإقــرار املدعــى عليــه‬\n     ‫‪.....‬بأخــذه مبلــغ ســتني ألــف ريــال مــن أمــوال الشــركة وأنــه هــو املبلــغ‬\n\n\n‫‪15‬‬\n\f‫الوحيــد الــذي ســحبه منهــا لوجــود حســاب خــاص بالشــركة وإلقــرار‬\n‫املدعــى عليــه ‪.....‬بإرجاعــه املبلــغ يف يــوم احلادثــة ولظهــور اخليانــة بتصــرف‬\n‫املدعــى عليهمــا املذكــور ومشــروعية التعزيــر عليــه ملخالفتــه قــول اهلل‬\n‫تعالــى (إن اهلل يأمركــم أن تــؤدوا األمانــات إلــى أهلهــا) فقــد ثبــت لــدي‬\n‫إدانــة املدعــى عليهمــا بخيانــة األمانــة وأخــذ مبلــغ مالــي مــن الشــركة‬\n‫وحكمــت عليهمــا مبــا يلــي ‪ /1 :‬ســجن املدعــى عليــه ‪.....‬ثالثــون شــهرا‬\n‫وجلــده ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات كل دفعــة خمســون‬\n‫جلــدة ‪ /2‬ســجن املدعــى عليــه ‪.....‬ســنة وجلــده مائــة وعشــرين جلــدة‬\n‫مفرقــة علــى دفعتــن كل دفعــة ســتون جلــدة والســجن احملكــوم بــه‬\n‫يبــدأ مــن تاريــخ اإليقــاف واجللــد أمــام النــاس وبــن كل دفعتــن عشــرة‬\n‫أيــام وبعرضــه عليهمــا قــرر املدعــى عليهمــا القناعــة وقــرر املدعــي‬\n‫العــام االعتــراض مكتفيــا بالئحــة الدعــوى جــرى النطــق باحلكــم يف‬\n‫‪1434/03/14‬ه ـ وأغلقــت اجللســة الســاعة العاشــرة والنصــف وعليــه‬\n‫جــرى التوقيــع وصلــى اهلل علــى نبينــا محمــد ‪ .‬حــرر يف ‪1434/3/14‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم‬\n‫‪ 34275988‬وتاريــخ ‪1434/6/24‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬واملســجل برقــم ‪34227186‬‬\n‫وتاريــخ ‪1434/5/29‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد كل مــن‪/‬‬\n‫‪( .......... -2 ...... -1‬مينــي اجلنســية) التهامهمــا بخيانــة األمانــة وأخــذ مبلــغ‬\n‫مالــي علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل بــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n\n\n                                                                                          ‫‪16‬‬\n\f     ‫قررنــا باألكثريــة املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                            ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪17‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":10,"source_page_end":17,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d0011d660d22b687b7c25836f534e83cc0ac2efc4edec27a7c8747f77500c937","normalized_text_hash":"1a939c67b38ebfb660aeeadcd1a38efc735dcedc527b9b79263006f3e3763447","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p10-34227186"}]$archive_payload$::jsonb) AS x LIMIT 25
